INSERT INTO `kontak_kami` (`id`, `feature_id`, `title`, `title_en`, `description`, `description_en`, `type`, `published_at`, `link_text`, `link_url`, `images`, `extra_data`, `order`, `is_active`, `views`, `shares`, `created_at`, `updated_at`) VALUES
(1, 6, 'Kontak Kami', 'Contact Us', '<div style=\"text-align: justify;\"><span style=\"color: inherit; white-space: pre-wrap;\">Kami siap membantu menjawab pertanyaan dan memberikan layanan terbaik untuk </span><span style=\"color: inherit; white-space: pre-wrap;\">kebutuhan kearsipan.</span></div><!--StartFragment--><span data-metadata=\"&lt;!--(figmeta)eyJmaWxlS2V5IjoiMWZxMU1uTEFvV1hLRE0wb1FHWHdwSSIsInBhc3RlSUQiOjExNzQ0OTg5OTgsImRhdGFUeXBlIjoic2NlbmUiLCJlbnZpcm9ubWVudCI6Ind3dy5maWdtYS5jb20iLCJzZWxlY3RlZE5vZGVEYXRhIjoiMjQ1OjkzMjc1fDMxfDAifQo=(/figmeta)--&gt;\"></span><!--EndFragment-->', '<div style=\"text-align: justify;\"><span style=\"color: inherit; white-space: pre-wrap;\">We are ready to help answer questions and provide the best service for </span><span style=\"color: inherit; white-space: pre-wrap;\">archival needs.</span></div><!--StartFragment--><span data-metadata=\"&lt;!--(figmeta)eyJmaWxlS2V5IjoiMWZxMU1uTEFvV1hLRE0wb1FHWHdwSSIsInBhc3RlSUQiOjExNzQ0OTg5OTgsImRhdGFUeXBlIjoic2NlbmUiLCJlbnZpcm9ubWVudCI6Ind3dy5maWdtYS5jb20iLCJzZWxlY3RlZE5vZGVEYXRhIjoiMjQ1OjkzMjc1fDMxfDAifQo=(/figmeta)--&gt;\"></span><!--EndFragment-->', 'kontak', '2026-05-17', NULL, NULL, NULL, '{\"cards\": [{\"icon\": \"phone\", \"title\": \"Layanan Informasi\", \"subtitle\": \"Untuk pertanyaan seputar kearsipan\", \"title_en\": \"Information Services\", \"subtitle_en\": \"For questions regarding archives\"}, {\"icon\": \"message\", \"title\": \"Layanan Arsip Statis\", \"subtitle\": \"Penyediaan arsip statis kepada pengguna arsip statis untuk kepentingan pemerintahan, pembangunan, penelitian dan ilmu pengetahuan untuk kesejahteraan rakyat sesuai kaidah-kaidah kearsipan demi kemaslahatan bangsa.\", \"title_en\": \"Static Archive Service\", \"subtitle_en\": \"Providing static archives to users of static archives for the purposes of government, development, research and science for the welfare of the people in accordance with archival principles for the benefit of the nation.\"}], \"email\": \"info@anri.go.id\", \"telepon\": \"(021) 7805851\", \"twitter\": \"\", \"youtube\": \"\", \"facebook\": \"\", \"whatsapp\": \"\", \"instagram\": \"https://www.instagram.com/arsipnasionalri/\", \"top_cards\": [{\"icon\": \"map\", \"title\": \"Bandung\", \"subtitle\": \"Lokasi Strategis\", \"title_en\": \"Bandung\", \"subtitle_en\": \"Strategic Location\"}, {\"icon\": \"building\", \"title\": \"Jawa Barat\", \"subtitle\": \"Depot Pertama\", \"title_en\": \"West Java\", \"subtitle_en\": \"First Depot\"}, {\"icon\": \"clock\", \"title\": \"5 Hari\", \"subtitle\": \"Layanan\", \"title_en\": \"5 Days\", \"subtitle_en\": \"Service\"}], \"alamat_lengkap\": \"Alamat Lengkap\\r\\nJalan Ciwastra, Mekarjaya, Kecamatan Rancasari, Kota Bandung, Jawa Barat\\r\\n\\r\\nKode Pos\\r\\n40292\", \"alamat_lengkap_en\": \"Complete Address\\r\\nJalan Ciwastra, Mekarjaya, Rancasari District, Bandung City, West Java\\r\\n\\r\\nPostal Code\\r\\n40292\", \"jam_section_title\": \"Jadwal & Jam Operasional\", \"cards_section_title\": \"Saluran Layanan\", \"alamat_section_title\": \"Informasi Kontak & Alamat\", \"jam_operasional_desc\": \"Waktu pelayanan Depot Arsip Berkelanjutan Bandung dibuka pada jadwal berikut:\", \"jam_operasional_list\": [{\"jam\": \"07.30 - 16.00 WIB\", \"hari\": \"Senin - Kamis\", \"hari_en\": \"Monday - Thursday\"}, {\"jam\": \"07.30 - 16.30 WIB\", \"hari\": \"Jumat\", \"hari_en\": \"Friday\"}], \"jam_section_title_en\": \"Schedule & Operational Hours\", \"cards_section_title_en\": \"Service Channel\", \"alamat_section_title_en\": \"Contact Information & Address\", \"jam_operasional_desc_en\": \"Bandung Continuous Archives Depot service times are open on the following schedule:\"}', 1, 1, 52, 4, '2026-05-17 05:00:40', '2026-06-14 06:45:48');
INSERT INTO `layanan_publiks` (`id`, `feature_id`, `title`, `title_en`, `description`, `description_en`, `type`, `published_at`, `link_text`, `link_url`, `images`, `extra_data`, `order`, `is_active`, `views`, `shares`, `created_at`, `updated_at`) VALUES
(1, 19, 'Layanan Pendaftaran Kunjungan', 'Visit Registration Service', '<div style=\"text-align: justify;\"><span style=\"white-space: pre-wrap;\">Arsip Nasional Republik Indonesia (ANRI) melalui Depot Arsip Berkelanjutan Bandung memberikan kesempatan kepada masyarakat untuk belajar dan mengenal kearsipan secara langsung. Melalui kegiatan kunjungan edukatif ini, diharapkan masyarakat dapat meningkatkan pemahaman dan kesadaran akan pentingnya arsip sebagai sumber informasi dan sejarah. Kunjungan ini juga menjadi sarana pembelajaran mengenai pengelolaan arsip, pemanfaatan arsip statis, serta penelusuran sumber sejarah yang tersimpan di Depot Arsip ANRI Bandung.</span></div><div style=\"text-align: justify;\"><!--EndFragment--></div><!--StartFragment--><span data-metadata=\"&lt;!--(figmeta)eyJmaWxlS2V5IjoiMWZxMU1uTEFvV1hLRE0wb1FHWHdwSSIsInBhc3RlSUQiOjg4OTQ2NzcsImRhdGFUeXBlIjoic2NlbmUiLCJlbnZpcm9ubWVudCI6Ind3dy5maWdtYS5jb20iLCJzZWxlY3RlZE5vZGVEYXRhIjoiMjQ1OjkyMTUwfDMxfDAifQo=(/figmeta)--&gt;\"></span><!--EndFragment-->', '<div style=\"text-align: justify;\"><span style=\"white-space: pre-wrap;\">The National Archives of the Republic of Indonesia (ANRI) through the Bandung Sustainable Archives Depot provides opportunities for the public to learn and get to know archives directly. Through this educational visit, it is hoped that the public can increase understanding and awareness of the importance of archives as a source of information and history. This visit was also a means of learning about archive management, the use of static archives, as well as searching for historical sources stored at the ANRI Bandung Archives Depot.</span></div><div style=\"text-align: justify;\"><!--EndFragment--></div><!--StartFragment--><span data-metadata=\"&lt;!--(figmeta)eyJmaWxlS2V5IjoiMWZxMU1uTEFvV1hLRE0wb1FHWHdwSSIsInBhc3RlSUQiOjg4OTQ2NzcsImRhdGFUeXBlIjoic2NlbmUiLCJlbnZpcm9ubWVudCI6Ind3dy5maWdtYS5jb20iLCJzZWxlY3RlZE5vZGVEYXRhIjoiMjQ1OjkyMTUwfDMxfDAifQo=(/figmeta)--&gt;\"></span><!--EndFragment-->', 'kunjungan', '2026-05-16', NULL, NULL, NULL, '{\"lib_objs\": [{\"text\": \"1. Mempermudah akses informasi terkait arsip dan sejarah.\"}, {\"text\": \"2. Mendukung kegiatan penelitian dan penulisan ilmiah.\"}, {\"text\": \"3. Menjadi sumber referensi dalam pengelolaan dan pelestarian arsip.\"}], \"file_name\": null, \"lib_cards\": [{\"desc\": \"Tersedia ribuan koleksi buku kearsipan, sejarah, dan literatur umum.\", \"title\": \"Koleksi Buku\"}, {\"desc\": \"Akses e-book, jurnal ilmiah, dan artikel digital terintegrasi.\", \"title\": \"Akses Digital\"}, {\"desc\": \"Ruang ber-AC yang nyaman dengan WiFi gratis untuk pemustaka.\", \"title\": \"Ruang Baca dan Belajar\"}], \"lib_hours\": \"Senin - Kamis : 08:30 - 15:00 WIB\\r\\nJumat : 08:30 - 15:30 WIB\", \"lib_procs\": [{\"desc\": \"Pengunjung melakukan pendaftaran atau masuk menggunakan akun layanan.\", \"title\": \"1. Registrasi / Login Akun\"}, {\"desc\": \"Pengunjung wajib mengisi buku tamu sebagai data administrasi pemustaka.\", \"title\": \"2. Mengisi Buku Tamu\"}, {\"desc\": \"Pengunjung dapat mencari dan memilih koleksi yang dibutuhkan melalui katalog.\", \"title\": \"3. Menelusuri Katalog\"}, {\"desc\": \"Koleksi yang terpilih dapat dibaca di ruang baca yang telah disediakan.\", \"title\": \"4. Membaca di Ruang Baca\"}], \"lib_rules\": [{\"text\": \"1. Dilarang membawa makanan/minuman ke dalam ruang baca.\"}, {\"text\": \"2. Tidak membawa tas ke meja baca (tersedia loker penyimpanan).\"}, {\"text\": \"3. Wajib menjaga ketenangan dan kebersihan perpustakaan.\"}], \"show_form\": 1, \"form_fields\": [{\"id\": \"name\", \"type\": \"text\", \"label\": \"Nama\", \"options\": null, \"label_en\": \"Name\", \"required\": \"1\"}, {\"id\": \"email\", \"type\": \"email\", \"label\": \"Email\", \"options\": null, \"label_en\": \"E-mail\", \"required\": \"1\"}, {\"id\": \"phone_office\", \"type\": \"text\", \"label\": \"No. Telpon Kantor\", \"options\": null, \"label_en\": \"No. Office Phone\"}, {\"id\": \"phone\", \"type\": \"text\", \"label\": \"No. Telpon\", \"options\": null, \"label_en\": \"No. Telephone\", \"required\": \"1\"}, {\"id\": \"institution\", \"type\": \"text\", \"label\": \"Instansi\", \"options\": null, \"label_en\": \"Institution\"}, {\"id\": \"position\", \"type\": \"text\", \"label\": \"Jabatan (dalam Instansi)\", \"options\": null, \"label_en\": \"Position (in the Agency)\"}, {\"id\": \"visit_date\", \"type\": \"date\", \"label\": \"Tanggal Kunjungan\", \"options\": null, \"label_en\": \"Date of Visit\", \"required\": \"1\"}, {\"id\": \"visit_time\", \"type\": \"select\", \"label\": \"Waktu Kunjungan\", \"options\": \"Pagi (07:30 - 12:00),Siang (13:00 - 16:00)\", \"label_en\": \"Visiting Times\", \"required\": \"1\", \"options_en\": \"Morning (07:30 - 12:00), Afternoon (13:00 - 16:00)\"}, {\"id\": \"visitor_count\", \"type\": \"number\", \"label\": \"Jumlah Pengunjung\", \"options\": null, \"label_en\": \"Number of Visitors\", \"required\": \"1\"}, {\"id\": \"visit_purpose\", \"type\": \"select\", \"label\": \"Tujuan Kunjungan\", \"options\": \"Edukasi,Penelitian,Kunjungan Kerja,Lainnya\", \"label_en\": \"Purpose of Visit\", \"required\": \"1\", \"options_en\": \"Education, Research, Work Visits, Others\"}, {\"id\": \"req_letter\", \"type\": \"file\", \"label\": \"Surat Permohonan\", \"options\": \"Format: pdf/doc, max 2MB\", \"label_en\": \"Application letter\", \"options_en\": \"Format: pdf/doc, max 2MB\"}], \"libur_dates\": [], \"show_jadwal\": 1, \"tutup_slots\": [{\"date\": \"2026-05-25\", \"slot\": \"pagi\", \"reason\": \"Slot Penuh / Ditutup\", \"max_quota\": 3, \"reason_en\": \"Full / Closed Slots\"}, {\"date\": \"2026-05-25\", \"slot\": \"siang\", \"reason\": \"Slot Penuh / Ditutup\", \"max_quota\": 2, \"reason_en\": \"Full / Closed Slots\"}, {\"date\": \"2026-05-26\", \"slot\": \"pagi\", \"reason\": \"Slot Penuh / Ditutup\", \"max_quota\": 0, \"reason_en\": \"Full / Closed Slots\"}], \"kuota_harian\": \"5\", \"lib_pdf_name\": null, \"statis_hours\": \"Senin - Kamis : 08:30 - 15:00 WIB\\r\\nJumat : 08:30 - 15:30 WIB\", \"title_jadwal\": null, \"laraska_hours\": \"Senin - Jumat : 09:00 - 15:00 WIB\\r\\nIstirahat (Senin - Kamis) : 12:00 - 13:00 WIB\\r\\n(Jumat) : 11:30 - 13:00 WIB\", \"laraska_steps\": [{\"desc\": \"Pengguna layanan mengajukan permohonan restorasi arsip melalui website DABB atau datang langsung ke loket pelayanan.\", \"title\": \"1. Pengajuan Layanan\"}, {\"desc\": \"Arsiparis memeriksa tingkat kerusakan arsip untuk menentukan metode restorasi yang tepat.\", \"title\": \"2. Pemeriksaan Kondisi Arsip\"}, {\"desc\": \"Tim teknis melakukan perbaikan arsip keluarga di laboratorium restorasi DABB.\", \"title\": \"3. Proses Restorasi Arsip\"}, {\"desc\": \"Pengguna mengambil arsip yang telah selesai direstorasi beserta salinan digitalnya.\", \"title\": \"4. Pengambilan Arsip\"}], \"lib_visit_btn\": \"Kunjungi Website Perpustakaan\", \"maklumat_date\": \"Jakarta, Juni 2024\", \"show_kalender\": 1, \"statis_stages\": [{\"title\": \"Penelusuran Mandiri via JIKN / SIKN\"}, {\"title\": \"Konsultasi dengan Petugas Layanan\"}, {\"title\": \"Mengisi Formulir Permintaan\"}, {\"title\": \"Pencarian Arsip oleh Petugas\"}, {\"title\": \"Penyerahan & Pembacaan Arsip\"}], \"lib_proc_title\": \"PROSEDUR LAYANAN PERPUSTAKAAN\", \"maklumat_title\": \"MAKLUMAT PELAYANAN\", \"show_pengajuan\": 1, \"auto_today_date\": 0, \"title_pengajuan\": null, \"jadwal_kunjungan\": \"Senin - Kamis : \\r\\nPagi 07:30 - 12:00 WIB\\r\\nSiang 13:00 - 16:00 WIB\\r\\n\\r\\nJumat : \\r\\nPagi 07:30 - 11:30 WIB\\r\\nSiang 13:00 - 16:30\", \"lib_photos_names\": \"\", \"lib_redirect_url\": null, \"maklumat_content\": \"\\\"Dengan ini, kami seluruh pelaksana kegiatan penyelamatan arsip dari dampak bencana menyatakan sanggup memberikan pelayanan LARASKA (Layanan Restorasi Arsip Keluarga) sesuai Standar Pelayanan yang telah ditetapkan dan apabila tidak menepati janji, kami siap menerima sanksi sesuai peraturan perundang-undangan yang berlaku.\\\"\", \"consultation_desc\": \"Kami melayani berbagai jenis konsultasi kearsipan, meliputi: Konsultasi Pengelolaan Arsip Dinamis (Penciptaan, Penggunaan, Pemeliharaan, dan Penyusutan), Konsultasi Pengolahan Arsip Statis, serta Konsultasi Alih Media dan Digitalisasi Arsip.\", \"is_login_required\": \"1\", \"maklumat_director\": \"Direktur Pelindungan dan Penyelamatan Arsip\", \"laraska_mech_title\": \"Mekanisme Layanan LARASKA\", \"statis_mech1_steps\": [{\"desc\": \"Membawa KTP/Identitas resmi yang berlaku dan surat pengantar dari instansi (bagi peneliti/mahasiswa).\", \"title\": \"1. Persyaratan\"}, {\"desc\": \"Melakukan pendaftaran di loket, menelusuri daftar arsip, dan mengisi form peminjaman arsip.\", \"title\": \"2. Prosedur\"}], \"statis_mech1_title\": \"Mekanisme Layanan Langsung\", \"statis_mech2_steps\": [{\"desc\": \"Mengirimkan surat permohonan resmi atau mengisi formulir daring melalui tautan yang disediakan.\", \"title\": \"1. Pengajuan Online\"}, {\"desc\": \"Petugas menelusuri arsip dan mengirimkan salinan digital (watermarked) ke email pemohon.\", \"title\": \"2. Pengiriman Salinan\"}], \"statis_mech2_title\": \"Mekanisme Layanan Tidak Langsung\", \"statis_order_hours\": \"Senin - Kamis : 08:30 - 14:00 WIB\\r\\nJumat : 08:30 - 14:30 WIB\", \"jadwal_kunjungan_en\": \"Monday - Thursday: \\r\\nMorning 07:30 - 12:00 WIB\\r\\nAfternoon 13:00 - 16:00 WIB\\r\\n\\r\\nFriday : \\r\\nMorning 07:30 - 11:30 WIB\\r\\nAfternoon 13:00 - 16:30\", \"pengajuan_kunjungan\": \"Kapasitas dalam 1 (satu) hari Pagi maks. 2 kunjungan, Siang maks. 2 kunjungan. Mohon isi informasi rencana kunjungan Anda sesuai dengan jadwal yang tersedia. Adapun kepastian jadwal kunjungan akan diinformasikan kembali oleh petugas yang menangani.\", \"consultation_success\": \"Permintaan konsultasi Anda telah terkirim. Petugas kami akan menghubungi Anda melalui email yang dicantumkan.\", \"consultation_form_send\": \"Kirim Permintaan Konsultasi\", \"pengajuan_kunjungan_en\": \"Capacity in