INSERT INTO `virtual_slideshow_slides` (`id`, `feature_id`, `feature_page_id`, `slide_type`, `title`, `title_en`, `subtitle`, `subtitle_en`, `description`, `description_en`, `images`, `image_urls`, `video_url`, `video_file`, `carousel_video_urls`, `layout`, `bg_color`, `info_popup`, `order`, `created_at`, `updated_at`) VALUES
(51, 72, 14, 'hero', 'Citra Daerah Jawa Barat Dalam Arsip', 'Regional Image of West Java in the Archives', NULL, NULL, '<div style=\"text-align: center;\"><span style=\"font-size: 14pt; font-family: &quot;Arial Black&quot;, sans-serif; color: rgb(255, 255, 255);\">Provinsi Jawa Barat merupakan salah satu daerah yang memiliki kekayaan sejarah, budaya, serta dinamika sosial-politik yang penting dalam perjalanan bangsa Indonesia. Berbagai peristiwa, perkembangan pemerintahan, perjuangan kemerdekaan, hingga kemajuan masyarakatnya terekam dalam arsip sebagai memori kolektif daerah dan bangsa. Melalui arsip-arsip tersebut, citra Jawa Barat tidak hanya tercermin sebagai wilayah yang strategis dan kaya akan potensi alam serta budaya, tetapi juga sebagai daerah yang memiliki kontribusi besar dalam pembentukan identitas nasional, perkembangan pendidikan, ekonomi, dan perjuangan mempertahankan Negara Kesatuan Republik Indonesia.</span></div>', '<div style=\"text-align: center;\"><span style=\"font-size: 14pt; font-family: &quot;Arial Black&quot;, sans-serif; color: rgb(255, 255, 255);\">West Java Province is a region that has a rich history, culture and socio-political dynamics that are important in the journey of the Indonesian nation. Various events, developments in government, the struggle for independence, and the progress of society are recorded in archives as the collective memory of the region and nation. Through these archives, the image of West Java is not only reflected as a strategic region and rich in natural and cultural potential, but also as a region that has made a major contribution to the formation of national identity, educational and economic development and the struggle to maintain the Unitary State of the Republic of Indonesia.</span></div>', '[\"features/slideshow/DJU5gW7MoCpDD0eYIsBW74ra8XCkITtos0qghJGh.png\"]', NULL, NULL, NULL, NULL, 'center', '#ffffff', '{\"unified_image_order\": [{\"type\": \"upload\", \"uploadIndex\": 0}]}', 1, '2026-05-25 04:11:25', '2026-05-25 05:01:16'),
(52, 72, 14, 'text_carousel', 'A. Geografis', 'A. Geographic', NULL, NULL, '<div style=\"text-align: justify;\"><!--StartFragment--><div class=\"qMYqUG_convSearchResultHighlightRoot\"><div class=\"\" data-turn-id-container=\"request-WEB:e6a54c7f-54bf-4121-9744-7bbafc4dff28-0\" data-is-intersecting=\"true\"><section class=\"text-token-text-primary w-full focus:outline-none has-data-writing-block:pointer-events-none [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto R6Vx5W_threadScrollVars scroll-mb-[calc(var(--scroll-root-safe-area-inset-bottom,0px)+var(--thread-response-height))] scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" data-turn-id=\"request-WEB:e6a54c7f-54bf-4121-9744-7bbafc4dff28-0\" data-turn-id-container=\"request-WEB:e6a54c7f-54bf-4121-9744-7bbafc4dff28-0\" data-testid=\"conversation-turn-2\" data-scroll-anchor=\"false\" data-turn=\"assistant\"><div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)\"><div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\"><div class=\"flex max-w-full flex-col gap-4 grow\"><div data-message-author-role=\"assistant\" data-message-id=\"4ec01ffd-ed5f-42a7-93e2-b494e06478e7\" dir=\"auto\" data-message-model-slug=\"gpt-5-5\" class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1\" data-turn-start-message=\"true\" tabindex=\"0\"><div class=\"flex w-full flex-col gap-1 empty:hidden\"><div class=\"markdown prose dark:prose-invert wrap-break-word w-full dark markdown-new-styling\"><p data-start=\"0\" data-end=\"555\" data-is-last-node=\"\" data-is-only-node=\"\" style=\"text-align: justify; \"><!--StartFragment--><span style=\"font-size: 12pt;\">Geografis wilayah Jawa Barat dalam Citra Daerah ini digambarkan melalui berbagai arsip peta dan sketsa dari kawasan Priangan dan sekitarnya, mulai abad ke-19 hingga abad ke-20. Arsip tersebut meliputi peta Sukapura, Galunggung, Limbangan, Priangan Barat tahun 1830, sketsa Cipanas di Distrik Ciputri Kabupaten Cianjur, peta rencana Kota Bandung, peta daerah Cirebon, sketsa wilayah Puncak, serta peta Kota Bandung tahun 1946. Keseluruhan arsip ini memberikan gambaran mengenai kondisi wilayah, tata ruang, dan perkembangan geografis Jawa Barat pada masanya.</span><!--EndFragment--></p></div></div></div></div><div class=\"z-0 flex min-h-[46px] justify-start\"></div></div></div></section></div></div><div aria-hidden=\"true\" class=\"pointer-events-none -mt-px h-px translate-y-[calc(var(--scroll-root-safe-area-inset-bottom)-14*var(--spacing))]\"></div><!--EndFragment--></div>', '<div style=\"text-align: justify;\"><!--StartFragment--><div class=\"qMYqUG_convSearchResultHighlightRoot\"><div class=\"\" data-turn-id-container=\"request-WEB:e6a54c7f-54bf-4121-9744-7bbafc4dff28-0\" data-is-intersecting=\"true\"><section class=\"text-token-text-primary w-full focus:outline-none has-data-writing-block:pointer-events-none [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto R6Vx5W_threadScrollVars scroll-mb-[calc(var(--scroll-root-safe-area-inset-bottom,0px)+var(--thread-response-height))] scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" data-turn-id=\"request-WEB:e6a54c7f-54bf-4121-9744-7bbafc4dff28-0\" data-turn-id-container=\"request-WEB:e6a54c7f-54bf-4121-9744-7bbafc4dff28-0\" data-testid=\"conversation-turn-2\" data-scroll-anchor=\"false\" data-turn=\"assistant\"><div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)\"><div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\"><div class=\"flex max-w-full flex-col gap-4 grow\"><div data-message-author-role=\"assistant\" data-message-id=\"4ec01ffd-ed5f-42a7-93e2-b494e06478e7\" dir=\"auto\" data-message-model-slug=\"gpt-5-5\" class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1\" data-turn-start-message=\"true\" tabindex=\"0\"><div class=\"flex w-full flex-col gap-1 empty:hidden\"><div class=\"markdown prose dark:prose-invert wrap-break-word w-full dark markdown-new-styling\"><p data-start=\"0\" data-end=\"555\" data-is-last-node=\"\" data-is-only-node=\"\" style=\"text-align: justify; \"><!--StartFragment--><span style=\"font-size: 12pt;\">The geography of the West Java region in this Regional Image is depicted through various map archives and sketches from the Priangan area and its surroundings, from the 19th century to the 20th century. The archives include maps of Sukapura, Galunggung, Limbangan, West Priangan in 1830, a sketch of Cipanas in the Ciputri District, Cianjur Regency, a plan map of Bandung City, a map of the Cirebon area, a sketch of the Puncak area, as well as a map of Bandung City in 1946. This entire archive provides an overview of the regional conditions, spatial planning and geographical development of West Java at that time.</span><!--EndFragment--></p></div></div></div></div><div class=\"z-0 flex min-h-[46px] justify-start\"></div></div></div></section></div></div><div aria-hidden=\"true\" class=\"pointer-events-none -mt-px h-px translate-y-[calc(var(--scroll-root-safe-area-inset-bottom)-14*var(--spacing))]\"></div><!--EndFragment--></div>', '[\"features/slideshow/SHDrOCn3ciYIcm1E0qvtVuQ8xLeM2i0Sqs7FFuqU.png\", \"features/slideshow/SjqACWU804uIYQhGeJFlnlyvKkDI8lcwnHJwbaYa.png\", \"features/slideshow/TsF25aDdkcVDWU3SVifQUWQwc2o2mK6xUxGm2Jmb.png\", \"features/slideshow/PIOtCLDiAxpVUAlwcRSeGboIJmBqMJFzrGRQ6OT3.png\", \"features/slideshow/UWrouhaHo3giKvV3NEiUfjCGrrmgP1l4PPdgechh.png\", \"features/slideshow/oJBQkw7wfdY2z96yfGYrk3Y4VYLwijYpe148qUwD.png\", \"features/slideshow/IoqciIKlUGuPqIIDplErTZkMG64dtR7yOtZPlGGu.png\"]', NULL, NULL, NULL, NULL, 'right', '#ffffff', '{\"carousel_media_type\": \"images\", \"unified_image_order\": [{\"type\": \"upload\", \"uploadIndex\": 0}, {\"type\": \"upload\", \"uploadIndex\": 1}, {\"type\": \"upload\", \"uploadIndex\": 2}, {\"type\": \"upload\", \"uploadIndex\": 3}, {\"type\": \"upload\", \"uploadIndex\": 4}, {\"type\": \"upload\", \"uploadIndex\": 5}, {\"type\": \"upload\", \"uploadIndex\": 6}], \"carousel_video_order\": []}', 2, '2026-05-25 04:15:29', '2026-05-25 08:26:20'),
(53, 72, 14, 'text_carousel', 'B. Pemerintahan', 'B. Governance', NULL, NULL, '<div style=\"text-align: justify;\"><!--StartFragment--><p><span style=\"font-size: 12pt;\">Perjalanan sejarah pemerintahan ditampilkan melalui berbagai arsip penting yang memuat perjanjian politik, silsilah kekuasaan, catatan perjalanan, pengakuan kekuasaan kolonial, perjuangan rakyat, administrasi pemerintahan daerah, hingga pembentukan dan program kerja pemerintahan daerah pada masa Hindia Belanda.</span></p></div>', '<div style=\"text-align: justify;\"><!--StartFragment--><p><span style=\"font-size: 12pt;\">The historical journey of government is shown through various important archives containing political agreements, genealogies of power, travel notes, recognition of colonial power, people\'s struggles, regional government administration, and the formation and work programs of regional governments during the Dutch East Indies.</span></p></div>', '[\"features/slideshow/lFk598aCtsjxjzF3UV5y4vbcZJg7jDPq8Z7gVi8o.png\", \"features/slideshow/vSvw0tTnuwqE4BcCl3xhtaQcOBIJ8jpAvP1WC0jb.png\", \"features/slideshow/8K5w0p8No8NFp5foaVvyvVtXCVoJVNE7wH6myihK.png\", \"features/slideshow/OecFQlIeeOp8esOLvlA7nH5hBXyGxCs17tjqD0K8.png\", \"features/slideshow/LrU5XcGLe2zNpICNVnVMMadwhldLBy2tbb53e9LY.png\", \"features/slideshow/srC9vcVcXNsOgaUkatV48FWrGQbk8IbGXD2a3HDy.png\", \"features/slideshow/PTYTA7s3WjLORagpQqg34qPU92P5RiF2BoPpUuwO.png\", \"features/slideshow/7LhZYbVeIfICNYC3OdKN4vVPPt2rjcTRjs9P3a45.png\", \"features/slideshow/X2cIeNcDKW5UvuzcCCpq0qUTP61I4LoipQuX1EAi.png\", \"features/slideshow/ma3YcLF6EsR0NpoCOGUGCKAahwiFwjOx18vK74PV.png\", \"features/slideshow/BWW7yfzjbhbuCo0gVD6eXcwlIFBFUdoUCnrhHr0I.png\", \"features/slideshow/rBtAGyxYSPqmTHolZfvmECTKwMpP7RYb5AEriCgX.png\", \"features/slideshow/vsmdS3qaTsXNqk885IjnUAC8uVBxFhOkfTG8pVaS.png\", \"features/slideshow/RXJgWFzTDiDoWbb33yONcKfI6tCO034rKhm0EGpP.png\", \"features/slideshow/LnHdvMXCS7BRjGUrCCxjzq4QCuhP699fKsge3jmi.png\", \"features/slideshow/moOv1xkfuEq3RbO9khdVDntVl3cpdYNGOVP2RuW8.png\", \"features/slideshow/PhFPMiVzL6xp6ejZNfrGd70LeJTqkPVKYqM1eip5.png\", \"features/slideshow/ZT0VQSljTiZsE6h21RCDT6V7WAhqRItazedhID1P.png\", \"features/slideshow/L3eQrzGXaEYkuQRWbtz91TgHEmdZehbwed6ORZtF.png\", \"features/slideshow/rNO5AWSxDqkXZMaaA25noywSaLSxdzityx5IMy3G.png\", \"features/slideshow/Z0yQvDfuqSbvTs50G6YDQpBDUvglSxzKmCI1ixpN.png\", \"features/slideshow/y5aExjVPnbnP594ZlI2qAj0vbZ2OipoOER4Tlrys.png\", \"features/slideshow/ijEqi4X6SDNCkzu0XNdc3i3F1dKb4pHMHT97kt1D.png\"]', NULL, NULL, NULL, NULL, 'right', '#ffffff', '{\"carousel_media_type\": \"images\", \"unified_image_order\": [{\"type\": \"upload\", \"uploadIndex\": 0}, {\"type\": \"upload\", \"uploadIndex\": 1}, {\"type\": \"upload\", \"uploadIndex\": 2}, {\"type\": \"upload\", \"uploadIndex\": 3}, {\"type\": \"upload\", \"uploadIndex\": 4}, {\"type\": \"upload\", \"uploadIndex\": 5}, {\"type\": \"upload\", \"uploadIndex\": 6}, {\"type\": \"upload\", \"uploadIndex\": 7}, {\"type\": \"upload\", \"uploadIndex\": 8}, {\"type\": \"upload\", \"uploadIndex\": 9}, {\"type\": \"upload\", \"uploadIndex\": 10}, {\"type\": \"upload\", \"uploadIndex\": 11}, {\"type\": \"upload\", \"uploadIndex\": 12}, {\"type\": \"upload\", \"uploadIndex\": 13}, {\"type\": \"upload\", \"uploadIndex\": 14}, {\"type\": \"upload\", \"uploadIndex\": 15}, {\"type\": \"upload\", \"uploadIndex\": 16}, {\"type\": \"upload\", \"uploadIndex\": 17}, {\"type\": \"upload\", \"uploadIndex\": 18}, {\"type\": \"upload\", \"uploadIndex\": 19}, {\"type\": \"upload\", \"uploadIndex\": 20}, {\"type\": \"upload\", \"uploadIndex\": 21}, {\"type\": \"upload\", \"uploadIndex\": 22}], \"carousel_video_order\": []}', 3, '2026-05-25 04:53:25', '2026-05-26 02:12:11'),
(55, 72, 14, 'text_carousel', 'C. Pertahanan dan Keamanan', 'C. Defense and Security', NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 16px;\">Mengarungi dua dekade penuh gejolak (1946–1965), Jawa Barat menjadi panggung utama bagi berbagai peristiwa bersejarah yang membentuk identitas politik dan keamanan Indonesia. Rekam jejak heroisme ini diawali dengan pengorbanan epik pada peristiwa Bandung Lautan Api dan ketangguhan Pasukan Siliwangi yang harus berhijrah akibat Agresi Militer Belanda, sebelum akhirnya kembali menyongsong kedaulatan RI. Tak hanya menjadi saksi perjuangan bersenjata, tanah Pasundan juga menjadi pusat diplomasi dunia saat menjadi tuan rumah Konferensi Panca Negara di Bogor dan Konferensi Asia Afrika di Bandung (1955) yang melahirkan rumusan agung Dasasila Bandung. Memori kolektif bangsa ini kemudian disempurnakan oleh potret dinamika demokrasi masa lalu dan deretan amanat perdamaian dari Presiden Soekarno, yang berpuncak pada penganugerahan Bintang Kehormatan Sam Karya kepada Kodam Siliwangi pada tahun 1965 sebagai lambang abadi pelindung negara.</span></div>', '<div style=\"text-align: justify;\"><span style=\"font-size: 16px;\">After two tumultuous decades (1946–1965), West Java became the main stage for various historical events that shaped Indonesia\'s political and security identity. This track record of heroism begins with the epic sacrifice during the Bandung Sea of ​​Fire incident and the resilience of the Siliwangi Troops who had to emigrate due to Dutch Military Aggression, before finally returning to welcome the sovereignty of the Republic of Indonesia. Not only was it a witness to armed struggle, the land of Pasundan also became the center of world diplomacy when it hosted the Five Country Conference in Bogor and the Asian-African Conference in Bandung (1955) which gave birth to the great formulation of the Bandung Principles. The collective memory of this nation was then refined by a portrait of the dynamics of past democracy and a series of peace mandates from President Soekarno, culminating in the awarding of the Sam Karya Honorary Star to the Siliwangi Military Command in 1965 as an eternal symbol of protector of the country.</span></div>', '[\"features/slideshow/YpB8MJN0dDlkmQuug7TeoI8ZUJSk9CNr83SIjmyO.png\", \"features/slideshow/4xgghiioODS0uqgdBqTYvtuMP82fbDSZ00TNJyNt.png\", \"features/slideshow/x649wPgb3R7AojSpHiaTXQWIWluZlUfwOMFTsMiy.png\", \"features/slideshow/nrX9sJycJLFt7AeR8e2I0ttfdd8aOrYrBXRFXAQN.png\", \"features/slideshow/jDDhz9qKBvCrvQYsmqAy2RpojvdxMBiHPVz5Gng1.png\", \"features/slideshow/mkTcemtbLSgU4YoDaEL40fc5H2yNLLW3O1wHyRev.png\", \"features/slideshow/COT7morK1f2vVtGFlnxUmZfRRuVJ823X1ZlqOadh.png\", \"features/slideshow/XnOnJ6rOdbUYD9ZZWJIkVPLhBy2jnIFfEFB72QCU.png\", \"features/slideshow/RtTo8Eqndp4v3l2bmy2gXNYtt8Cueg7WmsEk56Hc.png\", \"features/slideshow/VzrN5YyZKLhSAsMRYHS4yNL5AY1a2ZY1l1YBAhJ4.png\", \"features/slideshow/wgriA9YFSSgwkyBkzKN30y4QlGl5gdma00KwMoev.png\", \"features/slideshow/JbBBwZfpwQYiPeyS95jWzT9IiokFwb0KFm3yWdcC.png\", \"features/slideshow/4ZBhzkSDSwCey0HhHVU5zAIyMSrwlz5MnhgQYELz.png\", \"features/slideshow/T0lfCb5D7dlrpgmXIuLMgQJSUjf5Q5LP25vkBn9Z.png\", \"features/slideshow/DchsrKHwGquBh8jSlDkeSwLAEX2UsgReR07xgCcI.png\", \"features/slideshow/aa69AxVHRSczyNgy2cLCmbbkp9QswL3ixsWxRGie.png\", \"features/slideshow/AEFZlfQBZcZufAfaLkGNS2LVQD4YAGjb0CyvjnyI.png\", \"features/slideshow/2G5CTpDOINqErBa0rSA2cyVTe3VToIqGHZefbK5y.png\", \"features/slideshow/MYc3GGMiWrlOU5P5kT7ixPyTQEsXjXABZZ7xJbOY.png\", \"features/slideshow/r92CC8xr9sDacOp4CoVTQ6eg8x4yskjwlPMb3Jbx.png\", \"features/slideshow/pH6k9LyAJEMqk9dzxgZHHOwfCT9ZM9sNL3Ddhcad.png\", \"features/slideshow/4QCG4htWJAHiYJ6mLHhhXm10VbXcTmmIgb596RdH.png\", \"features/slideshow/Y5Qg2xjvFWPXS8ffzRxAvD8z7Y2rYNjZo9DXAYcp.png\", \"features/slideshow/xdHqkZXF7F89CeP5PTSvEnUm4vM6vNNzIbNTflIa.png\", \"features/slideshow/ix9k31XDDtS6DZFmOvOGp4nUpGs2hbZojbcfgeUJ.png\", \"features/slideshow/fkkLM56Kdnn57eeAI88pPz7hbQQ6eClLN0eBUMfi.png\", \"features/slideshow/ZP7BBaDqqPwYGFrrgI3s2E4rOtuPe7jcvqhAFba7.png\", \"features/slideshow/qm5MDWN3p8R1GxI5vUH4y2GQiDMqg8oCZ3BZRgOJ.png\", \"features/slideshow/l6vueSMWHhvHoy6OxQFSzOCQHgSPzeWGDRPZcBp7.png\"]', NULL, NULL, NULL, NULL, 'right', '#ffffff', '{\"carousel_media_type\": \"images\", \"unified_image_order\": [{\"type\": \"upload\", \"uploadIndex\": 0}, {\"type\": \"upload\", \"uploadIndex\": 1}, {\"type\": \"upload\", \"uploadIndex\": 2}, {\"type\": \"upload\", \"uploadIndex\": 3}, {\"type\": \"upload\", \"uploadIndex\": 4}, {\"type\": \"upload\", \"uploadIndex\": 5}, {\"type\": \"upload\", \"uploadIndex\": 6}, {\"type\": \"upload\", \"uploadIndex\": 7}, {\"type\": \"upload\", \"uploadIndex\": 8}, {\"type\": \"upload\", \"uploadIndex\": 9}, {\"type\": \"upload\", \"uploadIndex\": 10}, {\"type\": \"upload\", \"uploadIndex\": 11}, {\"type\": \"upload\", \"uploadIndex\": 12}, {\"type\": \"upload\", \"uploadIndex\": 13}, {\"type\": \"upload\", \"uploadIndex\": 14}, {\"type\": \"upload\", \"uploadIndex\": 15}, {\"type\": \"upload\", \"uploadIndex\": 16}, {\"type\": \"upload\", \"uploadIndex\": 17}, {\"type\": \"upload\", \"uploadIndex\": 18}, {\"type\": \"upload\", \"uploadIndex\": 19}, {\"type\": \"upload\", \"uploadIndex\": 20}, {\"type\": \"upload\", \"uploadIndex\": 21}, {\"type\": \"upload\", \"uploadIndex\": 22}, {\"type\": \"upload\", \"uploadIndex\": 23}, {\"type\": \"upload\", \"uploadIndex\": 24}, {\"type\": \"upload\", \"uploadIndex\": 25}, {\"type\": \"upload\", \"uploadIndex\": 26}, {\"type\": \"upload\", \"uploadIndex\": 27}, {\"type\": \"upload\", \"uploadIndex\": 28}], \"carousel_video_order\": []}', 4, '2026-05-25 06:29:26', '2026-05-25 08:43:03'),
(56, 72, 14, 'text_carousel', 'D. Perekonomian dan Perindustrian', 'D. Economy and Industry', NULL, NULL, '<p style=\"text-align: justify; margin-bottom: 0px; font-style: normal; font-variant-caps: normal; font-stretch: normal; line-height: normal; font-size-adjust: none; font-kerning: auto; font-variant-alternates: normal; font-variant-ligatures: normal; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-position: normal; font-feature-settings: normal; font-optical-sizing: auto; font-variation-settings: normal;\"><span style=\"font-family: inherit; font-size: 12pt;\">Kegiatan perekonomian dan perindustrian di Jawa Barat tergambar melalui arsip foto dan dokumen tentang perkembangan perbankan, perdagangan, industri tekstil, keramik, batik, anyaman, sepatu, hingga industri ban pada 1915–1970-an di berbagai daerah seperti Bandung, Tasikmalaya, Bogor, dan Sukabumi. Arsip tersebut juga menunjukkan perkembangan koperasi, pasar rakyat, hubungan ekonomi internasional melalui Food and Agriculture Organization, serta kemajuan industri nasional yang melibatkan Mohammad Hatta dan LIPNUR.</span></p>', '<p style=\"text-align: justify; margin-bottom: 0px; font-style: normal; font-variant-caps: normal; font-stretch: normal; line-height: normal; font-size-adjust: none; font-kerning: auto; font-variant-alternates: normal; font-variant-ligatures: normal; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-position: normal; font-feature-settings: normal; font-optical-sizing: auto; font-variation-settings: normal;\"><span style=\"font-family: inherit; font-size: 12pt;\">Economic and industrial activities in West Java are depicted through photo archives and documents regarding the development of banking, trade, textile, ceramic, batik, woven, shoe and tire industries in the 1915–1970s in various regions such as Bandung, Tasikmalaya, Bogor and Sukabumi. The archives also show the development of cooperatives, people\'s markets, international economic relations through the Food and Agriculture Organization, as well as the progress of national industry involving Mohammad Hatta and LIPNUR.</span></p>', '[\"features/slideshow/wFjDUjbCczydJ0RAUtgaaDFU5oFDDk92c98dJ0hc.png\", \"features/slideshow/eGA5eCY3jPNrepDJuOEjrbMjnt8fQH9klKfx6LGI.png\", \"features/slideshow/hv31kTYEsvMMY5UxngxoS4GBLnhtu3Kz3ghyDnfy.png\", \"features/slideshow/s3Ev674g7ruagLswwQ4SABT59oXC7XPYdhL6GsDN.png\", \"features/slideshow/nEAmTML0P4le6XgO0yqyf8aVYx4IlsYXi626Ct1H.png\", \"features/slideshow/j9EecdHHgEQmFCbSIUqA0TphBWsiBJklNEqUmsJf.png\", \"features/slideshow/R8J5gHNHkE73OigVfPcfvjk9VtBErIY0pZmxYLud.png\", \"features/slideshow/m1TldJd1MIXqDEztk4FY6uUVDcptDMH4i1YqVg23.png\", \"features/slideshow/OxJuAJWAnLBeABTlvvTQjwS4fzvCtiBWa318EypN.png\", \"features/slideshow/XUjaUWcRk125skzle53XBmA7JeuJK7SW86uD2Ak0.png\", \"features/slideshow/dILrxL7Y2ck9pWfDB0s0VUJsLmyGuxl9AGYayn2p.png\", \"features/slideshow/y6Rsz5OJi0Ms57BO8WRwK9Z42SBOIDWZjhYp4wCc.png\", \"features/slideshow/JfGF24MjnPCz2BTwBKg0KXTiT18NXnb5MDG8GQvL.png\", \"features/slideshow/TsbfxJtg5cyDooJg4TvshnmIiQVIaXbOOkvwzIpi.png\", \"features/slideshow/BqosNtcrd6UKr41VKxwBZ0UyNWXOkIzen41c8e67.png\", \"features/slideshow/Mk312kjMSZ35kqA6fHGtlpnNpYO80EBkrY6F1uHz.png\", \"features/slideshow/omRcx6llPgW2ozQ5xwWo44VAjgNQeXwkZr1V0IbF.png\", \"features/slideshow/6FYW4X3nU53GyEKcITgdwiv3M17LnN2UFaAwHgQA.png\", \"features/slideshow/j4C6vxiWBk2H0I0qYzu7UuHxIi9QQLTk4ABZ10sI.png\", \"features/slideshow/GqRtOWg52gcQoheBo2lj2309dbJPaPOveHZfNgnJ.png\", \"features/slideshow/aYIjb0qp1AmbYHpYD4ScRNdvHiGnS6ajrlcaWZkB.png\"]', NULL, NULL, NULL, NULL, 'right', '#ffffff', '{\"carousel_media_type\": \"images\", \"unified_image_order\": [{\"type\": \"upload\", \"uploadIndex\": 0}, {\"type\": \"upload\", \"uploadIndex\": 1}, {\"type\": \"upload\", \"uploadIndex\": 2}, {\"type\": \"upload\", \"uploadIndex\": 3}, {\"type\": \"upload\", \"uploadIndex\": 4}, {\"type\": \"upload\", \"uploadIndex\": 5}, {\"type\": \"upload\", \"uploadIndex\": 6}, {\"type\": \"upload\", \"uploadIndex\": 7}, {\"type\": \"upload\", \"uploadIndex\": 8}, {\"type\": \"upload\", \"uploadIndex\": 9}, {\"type\": \"upload\", \"uploadIndex\": 10}, {\"type\": \"upload\", \"uploadIndex\": 11}, {\"type\": \"upload\", \"uploadIndex\": 12}, {\"type\": \"upload\", \"uploadIndex\": 13}, {\"type\": \"upload\", \"uploadIndex\": 14}, {\"type\": \"upload\", \"uploadIndex\": 15}, {\"type\": \"upload\", \"uploadIndex\": 16}, {\"type\": \"upload\", \"uploadIndex\": 17}, {\"type\": \"upload\", \"uploadIndex\": 18}, {\"type\": \"upload\", \"uploadIndex\": 19}, {\"type\": \"upload\", \"uploadIndex\": 20}], \"carousel_video_order\": []}', 5, '2026-05-25 06:31:38', '2026-05-26 02:13:24'),
(58, 72, 14, 'text_carousel', 'E. Pertanian dan Perkebunan', 'E. Agriculture and Plantation', NULL, NULL, '<div style=\"text-align: justify;\"><!--StartFragment--><div class=\"qMYqUG_convSearchResultHighlightRoot\"><div class=\"\" data-turn-id-container=\"request-WEB:6ec24936-b0f6-4bd2-828b-3d0fdcd84bb5-4\" data-is-intersecting=\"true\"><section class=\"text-token-text-primary w-full focus:outline-none has-data-writing-block:pointer-events-none [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto R6Vx5W_threadScrollVars scroll-mb-[calc(var(--scroll-root-safe-area-inset-bottom,0px)+var(--thread-response-height))] scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" data-turn-id=\"request-WEB:6ec24936-b0f6-4bd2-828b-3d0fdcd84bb5-4\" data-turn-id-container=\"request-WEB:6ec24936-b0f6-4bd2-828b-3d0fdcd84bb5-4\" data-testid=\"conversation-turn-10\" data-scroll-anchor=\"false\" data-turn=\"assistant\"><div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)\"><div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\"><div class=\"flex max-w-full flex-col gap-4 grow\"><div data-message-author-role=\"assistant\" data-message-id=\"99d8a9cf-a9ed-4249-b756-f52253337055\" dir=\"auto\" data-message-model-slug=\"gpt-5-5\" class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1\" data-turn-start-message=\"true\" tabindex=\"0\"><div class=\"flex w-full flex-col gap-1 empty:hidden\"><div class=\"markdown prose dark:prose-invert wrap-break-word w-full dark markdown-new-styling\"><p data-start=\"0\" data-end=\"967\" data-is-last-node=\"\" data-is-only-node=\"\" style=\"text-align: justify; \"><!--StartFragment--><span style=\"font-size: 12pt; font-family: inherit;\">Perkembangan sektor pertanian dan peternakan di Jawa Barat tergambar dalam arsip mengenai perkebunan kopi, teh, kina, dan sayuran, penanganan hama tanaman, penelitian pertanian, hingga kebijakan pemerintah terkait pertanian, perikanan, dan peternakan pada masa kolonial hingga awal kemerdekaan. Arsip tersebut juga mendokumentasikan aktivitas para pekerja perkebunan, petani di sawah, koleksi flora di Kebun Raya Bogor, serta kunjungan Wakil Presiden Mohammad Hatta ke Balai Penyelidikan Karet di Bogor tahun 1952.</span><!--EndFragment--></p></div></div></div></div><div class=\"z-0 flex min-h-[46px] justify-start\"></div><div class=\"mt-3 w-full empty:hidden\"><div class=\"text-center\"></div></div></div></div></section></div></div><div aria-hidden=\"true\" class=\"pointer-events-none -mt-px h-px translate-y-[calc(var(--scroll-root-safe-area-inset-bottom)-14*var(--spacing))]\"></div><!--EndFragment--></div>', '<div style=\"text-align: justify;\"><!--StartFragment--><div class=\"qMYqUG_convSearchResultHighlightRoot\"><div class=\"\" data-turn-id-container=\"request-WEB:6ec24936-b0f6-4bd2-828b-3d0fdcd84bb5-4\" data-is-intersecting=\"true\"><section class=\"text-token-text-primary w-full focus:outline-none has-data-writing-block:pointer-events-none [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto R6Vx5W_threadScrollVars scroll-mb-[calc(var(--scroll-root-safe-area-inset-bottom,0px)+var(--thread-response-height))] scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" data-turn-id=\"request-WEB:6ec24936-b0f6-4bd2-828b-3d0fdcd84bb5-4\" data-turn-id-container=\"request-WEB:6ec24936-b0f6-4bd2-828b-3d0fdcd84bb5-4\" data-testid=\"conversation-turn-10\" data-scroll-anchor=\"false\" data-turn=\"assistant\"><div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)\"><div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\"><div class=\"flex max-w-full flex-col gap-4 grow\"><div data-message-author-role=\"assistant\" data-message-id=\"99d8a9cf-a9ed-4249-b756-f52253337055\" dir=\"auto\" data-message-model-slug=\"gpt-5-5\" class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1\" data-turn-start-message=\"true\" tabindex=\"0\"><div class=\"flex w-full flex-col gap-1 empty:hidden\"><div class=\"markdown prose dark:prose-invert wrap-break-word w-full dark markdown-new-styling\"><p data-start=\"0\" data-end=\"967\" data-is-last-node=\"\" data-is-only-node=\"\" style=\"text-align: justify; \"><!--StartFragment--><span style=\"font-size: 12pt; font-family: inherit;\">The development of the agricultural and livestock sectors in West Java is depicted in archives regarding coffee, tea, quinine and vegetable plantations, management of plant pests, agricultural research, and government policies regarding agriculture, fisheries and animal husbandry from the colonial period to the beginning of independence. The archives also document the activities of plantation workers, farmers in rice fields, flora collections in the Bogor Botanical Gardens, as well as Vice President Mohammad Hatta\'s visit to the Rubber Research Center in Bogor in 1952.</span><!--EndFragment--></p></div></div></div></div><div class=\"z-0 flex min-h-[46px] justify-start\"></div><div class=\"mt-3 w-full empty:hidden\"><div class=\"text-center\"></div></div></div></div></section></div></div><div aria-hidden=\"true\" class=\"pointer-events-none -mt-px h-px translate-y-[calc(var(--scroll-root-safe-area-inset-bottom)-14*var(--spacing))]\"></div><!--EndFragment--></div>', '[\"features/slideshow/tOPkcf55M2I91qcyJJcofs8v2LzNJYCk3iGUvuQB.png\", \"features/slideshow/NEXBtU8nU9dPo57eLPcaQVLTuJnMKsD9hcKbPBhP.png\", \"features/slideshow/7Z8gZ8R8iX38H86Hkn93LYoedk86YouEOnfwy2Bb.png\", \"features/slideshow/UNMUwmiAxAV1Gz4SD0LwIR8INEhLAqC4Q2p3Um17.png\", \"features/slideshow/W4hisG9Kqto5Wu6RYa7JXfB0gMfD5uIVUw7FyyaF.png\", \"features/slideshow/Tvb4PlLyCqxEE2Od14IRAewg4QoQaXAUmLni3CFa.png\", \"features/slideshow/eAIYB6It0UAayIBqK0zgASxdot6txmRfP7ohQcqJ.png\", \"features/slideshow/VXFnDRs1VwNXVo25FM3ROnnkrwpOy4Wna8MqTvWG.png\", \"features/slideshow/iNfclRKLQoU9wbn2LzwUsVrgATBbl2fQzXmMFk9B.png\", \"features/slideshow/c93yeIXgkXCcFOgaTnIhLEUgbFZ4GNM35cJLFYQa.png\", \"features/slideshow/zClwbfOg2A098bi5JjwNvvuSt7ysMILj55Ppb7QI.png\", \"features/slideshow/WLvVwAMXxU062QlNQK8xxPg1yV0jec9UXmow524L.png\", \"features/slideshow/mjCmm7QWJ75am7OONXx1Vlt6XgXP1vEhGgGh5nCL.png\", \"features/slideshow/lPP2y7ZKdsBnrgaC997F6gkMYhUyFjXWxk6KdVjG.png\"]', NULL, NULL, NULL, NULL, 'right', '#ffffff', '{\"carousel_media_type\": \"images\", \"unified_image_order\": [{\"type\": \"upload\", \"uploadIndex\": 0}, {\"type\": \"upload\", \"uploadIndex\": 1}, {\"type\": \"upload\", \"uploadIndex\": 2}, {\"type\": \"upload\", \"uploadIndex\": 3}, {\"type\": \"upload\", \"uploadIndex\": 4}, {\"type\": \"upload\", \"uploadIndex\": 5}, {\"type\": \"upload\", \"uploadIndex\": 6}, {\"type\": \"upload\", \"uploadIndex\": 7}, {\"type\": \"upload\", \"uploadIndex\": 8}, {\"type\": \"upload\", \"uploadIndex\": 9}, {\"type\": \"upload\", \"uploadIndex\": 10}, {\"type\": \"upload\", \"uploadIndex\": 11}, {\"type\": \"upload\", \"uploadIndex\": 12}, {\"type\": \"upload\", \"uploadIndex\": 13}], \"carousel_video_order\": []}', 6, '2026-05-25 06:36:04', '2026-05-25 08:05:31'),
(59, 72, 14, 'text_carousel', 'F. Pendidikan', 'F. Education', NULL, NULL, '<div style=\"text-align: justify;\"><!--StartFragment--><span style=\"font-size: 12pt;\">Kegiatan pendidikan dalam arsip kertas dan foto menampilkan perkembangan pendidikan di Jawa Barat pada periode 1921–1964, mulai dari sekolah perempuan dan sekolah pribumi, perkembangan Technische Hooge School (kini </span><span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\" style=\"\"><span class=\"whitespace-normal\" style=\"font-size: 12pt;\">Institut Teknologi Bandung</span></span><span style=\"font-size: 12pt;\">), aktivitas mahasiswa, hingga fasilitas pendidikan sep</span><span style=\"font-size: 12pt;\">ert</span><span style=\"font-size: 12pt;\">i Observatorium Bosscha</span><span style=\"font-size: 12pt;\">. Arsip juga memperlihatkan peran Soekarno&nbsp;</span><span style=\"font-size: 12pt;\">dalam dunia pendidikan melalui peresmian kampus, pembangunan gedung pendidikan, pemberian gelar kehormatan, serta dukungan terhadap kegiatan mahasiswa dan perkembangan perguruan tinggi di Jawa Barat.</span><!--EndFragment--><!--EndFragment--><!--EndFragment--><!--EndFragment--><!--EndFragment--></div>', '<div style=\"text-align: justify;\"><!--StartFragment--><span style=\"font-size: 12pt;\">Educational activities in paper and photo archives show the development of education in West Java in the period 1921–1964, starting from women\'s schools and indigenous schools, the development of the Technische Hooge School (now </span><span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\" style=\"\"><span class=\"whitespace-normal\" style=\"font-size: 12pt;\">Bandung Institute of Technology</span></span><span style=\"font-size: 12pt;\">), student activities, to educational facilities sep</span><span style=\"font-size: 12pt;\">ert</span><span style=\"font-size: 12pt;\">i Bosscha Observatory</span><span style=\"font-size: 12pt;\">. Archives also show Soekarno\'s role </span><span style=\"font-size: 12pt;\">in the world of education through the inauguration of campuses, construction of educational buildings, awarding honorary degrees, as well as support for student activities and the development of higher education in West Java.</span><!--EndFragment--><!--EndFragment--><!--EndFragment--><!--EndFragment--><!--EndFragment--></div>', '[\"features/slideshow/LKc9LkOmispcApxzpTvuSmuUmQ9kWoFMjur5bq3j.png\", \"features/slideshow/nnRPkN8Sgw6uCbPE25dyI4UmOILJDNeT06OdnGHV.png\", \"features/slideshow/BeZMr9GFuil0nBklXhSMRelXqjTu6UQvtOZpcJOA.png\", \"features/slideshow/OsdNRawbRZyXlhiGLdO0NNbcP2j2qE4i0dHJT7ZA.png\", \"features/slideshow/nF36WK4FQTvsOEUBGPj3ATs3xmtSmLZpEGANoQfT.png\", \"features/slideshow/zpE6Rbdg58vBfrNizMKfMhRAkFxkGK3xVabWaLJR.png\", \"features/slideshow/JuYtSS1IA385EFa91KfkwvoDERPuLMo0jw3Ir6J1.png\", \"features/slideshow/ZCBHfmpKqdGD26rwTkvIx6tCXWttVwhDt3HemRXw.png\", \"features/slideshow/0P9MzKvvWBClWXh4c3oFJ6FrqGOmntvhBTIWDYYX.png\", \"features/slideshow/jkoSc8ziGbPC5hhtWVHjzgaKEN8cVT8Xg0tfuon3.png\", \"features/slideshow/SKKanDnNIKG0sxLNZfglqf17mTCB9nhJxfJXAwc4.png\", \"features/slideshow/0c9kPa4Oss4QoPB22EF57BL7s5R2CDqcYL7eq0PN.png\", \"features/slideshow/OKqHRTwRE3NTac9U8lDwPs3yoNXD878EXWmKe974.png\", \"features/slideshow/62So7Em3yPVZuF2xWmqO4M5gEO4eg5mZllCTBvSH.png\", \"features/slideshow/RiBdfmrucLpiJBHQFC4UnxBp7wOGDkpAihpYzdt6.png\", \"features/slideshow/zbeYv8on04kZhSORUpKAYZUE84JYztOES4EGco4F.png\", \"features/slideshow/IWcnCiR8tp1mQE25v8hz5QxCM5bB9upLgHjgaz6a.png\", \"features/slideshow/64ZCrRooBg1PaHTdNWTTql9YPktFDAkvctQ3DTbr.png\", \"features/slideshow/igH1pFAcMCStDQo5oK7clYnCFZAwKII30JmjCFf1.png\", \"features/slideshow/JNndDp8nDUh5L7fO8G7ihAe4TEfP0hxwbtXNWrjS.png\", \"features/slideshow/UPz35ohZTIyFBs4VhTdCodmmIrYl1Xe786YgJYO0.png\", \"features/slideshow/6bBySc6hYFFpOoTmsCTVdmheYIn1MN29FO64GpfO.png\", \"features/slideshow/kWbcQg83L7JeLln2oMuh7ZAEwGP9xoLhjlggKTBK.png\", \"features/slideshow/TNwVgOYyBNARpwjTyQh70vmSzWPEe8i6RVpqCYsj.png\", \"features/slideshow/fACCjbV8xK2kqEZ8PXWkpWpBUAmMZGY2W8gHnEXP.png\"]', NULL, NULL, NULL, NULL, 'right', '#ffffff', '{\"carousel_media_type\": \"images\", \"unified_image_order\": [{\"type\": \"upload\", \"uploadIndex\": 0}, {\"type\": \"upload\", \"uploadIndex\": 1}, {\"type\": \"upload\", \"uploadIndex\": 2}, {\"type\": \"upload\", \"uploadIndex\": 3}, {\"type\": \"upload\", \"uploadIndex\": 4}, {\"type\": \"upload\", \"uploadIndex\": 5}, {\"type\": \"upload\", \"uploadIndex\": 6}, {\"type\": \"upload\", \"uploadIndex\": 7}, {\"type\": \"upload\", \"uploadIndex\": 8}, {\"type\": \"upload\", \"uploadIndex\": 9}, {\"type\": \"upload\", \"uploadIndex\": 10}, {\"type\": \"upload\", \"uploadIndex\": 11}, {\"type\": \"upload\", \"uploadIndex\": 12}, {\"type\": \"upload\", \"uploadIndex\": 13}, {\"type\": \"upload\", \"uploadIndex\": 14}, {\"type\": \"upload\", \"uploadIndex\": 15}, {\"type\": \"upload\", \"uploadIndex\": 16}, {\"type\": \"upload\", \"uploadIndex\": 17}, {\"type\": \"upload\", \"uploadIndex\": 18}, {\"type\": \"upload\", \"uploadIndex\": 19}, {\"type\": \"upload\", \"uploadIndex\": 20}, {\"type\": \"upload\", \"uploadIndex\": 21}, {\"type\": \"upload\", \"uploadIndex\": 22}, {\"type\": \"upload\", \"uploadIndex\": 23}, {\"type\": \"upload\", \"uploadIndex\": 24}], \"carousel_video_order\": []}', 7, '2026-05-25 06:37:09', '2026-05-26 02:50:59'),
(60, 72, 14, 'text_carousel', 'G. Kesehatan', 'G. Health', NULL, NULL, '<div style=\"text-align: justify;\"><!--StartFragment--><span style=\"font-size: 12pt;\">Aspek kesehatan dalam Citra Daerah Jawa Barat ditampilkan melalui berbagai arsip yang menggambarkan perkembangan layanan kesehatan dan penanganan wabah di Jawa Barat. Arsip tersebut meliputi pembangunan gedung rehabilitasi epidemi di Sukabumi, aktivitas Institut Pasteur Bandung, Sanatorium Cisarua, kunjungan Presiden Soekarno ke PMI di Bogor, Konferensi WHO di Bandung, Balai Pengobatan Penyakit Kusta di Bekasi, hingga pendirian Rumah Sakit Khusus Ginjal Ny. R.A. Habibie. Arsip-arsip ini menunjukkan perkembangan fasilitas kesehatan, penelitian medis, serta upaya penanganan penyakit di Jawa Barat dari masa ke masa.</span><!--EndFragment--></div>', '<div style=\"text-align: justify;\"><!--StartFragment--><span style=\"font-size: 12pt;\">Health aspects in the West Java Regional Image are displayed through various archives that describe the development of health services and handling of the outbreak in West Java. The archives include the construction of an epidemic rehabilitation building in Sukabumi, the activities of the Bandung Pasteur Institute, the Cisarua Sanatorium, President Soekarno\'s visit to PMI in Bogor, the WHO Conference in Bandung, the Leprosy Treatment Center in Bekasi, and the establishment of the Ny. R.A. Habibie. These archives show the development of health facilities, medical research, and disease management efforts in West Java from time to time.</span><!--EndFragment--></div>', '[\"features/slideshow/4lBtRy8eIJMqVpt7taOic15y0kJvxvOIqhUabU82.png\", \"features/slideshow/VuCkbgn9MBotmeiREK6odCydZAf0DhoN3ocuejhk.png\", \"features/slideshow/9lN9yYK6IZ8WIGAXbnIXRou4IWPTQC9wEphDynCy.png\", \"features/slideshow/GeQ9MGPTbuXSTavwZhbALV07lfNvWMm1QgbRGTHr.png\", \"features/slideshow/oUfzXRi1sJThLWUN2rjnTFx3lJCnYpCvZOghsKrF.png\"]', NULL, NULL, NULL, NULL, 'right', '#ffffff', '{\"carousel_media_type\": \"images\", \"unified_image_order\": [{\"type\": \"upload\", \"uploadIndex\": 0}, {\"type\": \"upload\", \"uploadIndex\": 1}, {\"type\": \"upload\", \"uploadIndex\": 2}, {\"type\": \"upload\", \"uploadIndex\": 3}, {\"type\": \"upload\", \"uploadIndex\": 4}], \"carousel_video_order\": []}', 8, '2026-05-25 06:38:22', '2026-05-25 08:25:32'),
(61, 72, 14, 'text_carousel', 'H. Infrastruktur', 'H. Infrastructure', NULL, NULL, '<div style=\"text-align: justify;\"><!--StartFragment--><span style=\"font-size: 12pt; font-family: inherit;\">Pembangunan sarana Irigasi dapat dilihat dari Denah saluran air ledeng yang berasal dari rawa Cibinong 29 Januari 1801, pusat Tenaga Air di Lumajang Bandung Selatan tahun 1949, Proyek pembangunan Citra Jawa Barat dalam Arsip 33 Waduk serba guna Jatiluhur 18 April 1965, dan Amanat Presiden Soekarno pada waktu mengunjungi Proyek Waduk Serba Guna Jatiluhur di Purwakarta 19 September 1965</span><!--EndFragment--></div>', '<div style=\"text-align: justify;\"><!--StartFragment--><span style=\"font-size: 12pt; font-family: inherit;\">The construction of Irrigation facilities can be seen from the Plan of the piped water channel originating from the Cibinong swamp on January 29 1801, the Water Power center in Lumajang, South Bandung in 1949, the Citra West Java development project in the Jatiluhur Multi-Purpose Reservoir 33 Archives April 18 1965, and President Soekarno\'s message when visiting the Jatiluhur Multi-Purpose Reservoir Project in Purwakarta 19 September 1965</span><!--EndFragment--></div>', '[\"features/slideshow/8X8VHYrmJYCdg5f8RRPKU6e8tRgP18JZmiQeagjK.png\", \"features/slideshow/CsER9mXxOqWpkbJ60qQIehyMEoQcwZ3svKf6TFDy.png\", \"features/slideshow/fM8GD5nKCmFojNba2iQluB5vMArMEWsADnnXZYap.png\", \"features/slideshow/gTTzdFl6MJpenAs9G4qmu1fJJJh3y3K7isgeb8N0.png\", \"features/slideshow/auD0I3YDcUznrJ9IFkmNM8d5NB1zQMGiCewNFsky.png\", \"features/slideshow/pV70OiWIceDXPtG4NUvL8ltUbBIinmGJSjSRc4XR.png\", \"features/slideshow/h5HDIx7bvR9Saq5kXJuuQbhZTl2HFBZrt9adp4RP.png\", \"features/slideshow/mausL0Q7JRLcmQmbjWKxkxiNaBZEGSakOy1w7MmC.png\", \"features/slideshow/36B3fBV0pOIqT37kZ6t5NgOEA7lYSzPMipsfYjZY.png\", \"features/slideshow/sEFJBiIWrF339kCAN8cClJpLSSyZMVerqFdeZpzJ.png\", \"features/slideshow/FpsGt48QlH2uG9apjlDjy70O6sXbJtrxNUEQHW5i.png\", \"features/slideshow/KojEhTVdM3BcjIvVIxZ9CjWmC0hdzRVUkikvP5mr.png\", \"features/slideshow/QRwLCTqkrqEnwQDUlJWBsG1Bd95O2j2tvld0urzD.png\"]', NULL, NULL, NULL, NULL, 'right', '#ffffff', '{\"carousel_media_type\": \"images\", \"unified_image_order\": [{\"type\": \"upload\", \"uploadIndex\": 0}, {\"type\": \"upload\", \"uploadIndex\": 1}, {\"type\": \"upload\", \"uploadIndex\": 2}, {\"type\": \"upload\", \"uploadIndex\": 3}, {\"type\": \"upload\", \"uploadIndex\": 4}, {\"type\": \"upload\", \"uploadIndex\": 5}, {\"type\": \"upload\", \"uploadIndex\": 6}, {\"type\": \"upload\", \"uploadIndex\": 7}, {\"type\": \"upload\", \"uploadIndex\": 8}, {\"type\": \"upload\", \"uploadIndex\": 9}, {\"type\": \"upload\", \"uploadIndex\": 10}, {\"type\": \"upload\", \"uploadIndex\": 11}, {\"type\": \"upload\", \"uploadIndex\": 12}], \"carousel_video_order\": []}', 9, '2026-05-25 06:45:26', '2026-05-25 08:07:20'),
(62, 72, 14, 'text_carousel', 'I. Irigasi', 'I. Irrigation', NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-family: inherit; font-size: 12pt;\">Pembangunan sarana Irigasi dapat dilihat dari Denah saluran air ledeng yang berasal dari rawa Cibinong 29 Januari 1801, pusat Tenaga Air di Lumajang Bandung Selatan tahun 1949, Proyek pembangunan Citra Jawa Barat dalam Arsip 33 Waduk serba guna Jatiluhur 18 April 1965, dan Amanat Presiden Soekarno pada waktu mengunjungi Proyek Waduk Serba Guna Jatiluhur di Purwakarta 19 September 1965.</span></div>', '<div style=\"text-align: justify;\"><span style=\"font-family: inherit; font-size: 12pt;\">The construction of irrigation facilities can be seen from the plan of the piped water channel originating from the Cibinong swamp on January 29 1801, the water power center in Lumajang, South Bandung in 1949, the Citra West Java construction project in Archives 33 Jatiluhur multi-purpose reservoir April 18 1965, and the message from President Soekarno when visiting the Jatiluhur multi-purpose reservoir project in Purwakarta September 19, 1965.</span></div>', '[\"features/slideshow/jTjVGE8W71rRlbDSKUwaiLywSvIyAKr43Xr5t1Xu.png\", \"features/slideshow/hXAMIsYDYb7vG5i8gYov1jFWagww5LEHqh8PWrzi.png\", \"features/slideshow/CxNzoqJfdAOeKzCji1DQPsd2lfSDXtA2ssz15jY4.png\", \"features/slideshow/ACkSTyIiMGh1NcT7a50W2heOGlxxz5xxv4SfSYAO.png\"]', NULL, NULL, NULL, NULL, 'right', '#ffffff', '{\"carousel_media_type\": \"images\", \"unified_image_order\": [{\"type\": \"upload\", \"uploadIndex\": 0}, {\"type\": \"upload\", \"uploadIndex\": 1}, {\"type\": \"upload\", \"uploadIndex\": 2}, {\"type\": \"upload\", \"uploadIndex\": 3}], \"carousel_video_order\": []}', 10, '2026-05-25 06:48:53', '2026-05-25 08:06:11');
INSERT INTO `virtual_slideshow_slides` (`id`, `feature_id`, `feature_page_id`, `slide_type`, `title`, `title_en`, `subtitle`, `subtitle_en`, `description`, `description_en`, `images`, `image_urls`, `video_url`, `video_file`, `carousel_video_urls`, `layout`, `bg_color`, `info_popup`, `order`, `created_at`, `updated_at`) VALUES
(65, 72, 14, 'text_carousel', 'J. Pertambangan', 'J. Mining', NULL, NULL, '<div style=\"text-align: justify;\"><!--StartFragment--><div class=\"qMYqUG_convSearchResultHighlightRoot\"><div class=\"\" data-turn-id-container=\"request-WEB:e6a54c7f-54bf-4121-9744-7bbafc4dff28-3\" data-is-intersecting=\"true\"><section class=\"text-token-text-primary w-full focus:outline-none has-data-writing-block:pointer-events-none [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto R6Vx5W_threadScrollVars scroll-mb-[calc(var(--scroll-root-safe-area-inset-bottom,0px)+var(--thread-response-height))] scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" data-turn-id=\"request-WEB:e6a54c7f-54bf-4121-9744-7bbafc4dff28-3\" data-turn-id-container=\"request-WEB:e6a54c7f-54bf-4121-9744-7bbafc4dff28-3\" data-testid=\"conversation-turn-8\" data-scroll-anchor=\"false\" data-turn=\"assistant\"><div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)\"><div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\"><div class=\"flex max-w-full flex-col gap-4 grow\"><div data-message-author-role=\"assistant\" data-message-id=\"cce3f6f4-a1b4-483b-a7e8-ef28abf4bff4\" dir=\"auto\" data-message-model-slug=\"gpt-5-5\" class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1\" data-turn-start-message=\"true\" tabindex=\"0\"><div class=\"flex w-full flex-col gap-1 empty:hidden\"><div class=\"markdown prose dark:prose-invert wrap-break-word w-full dark markdown-new-styling\"><p data-start=\"0\" data-end=\"459\" data-is-last-node=\"\" data-is-only-node=\"\" style=\"text-align: justify; \"><span style=\"font-size: 12pt;\">Aspek pertambangan dalam Citra Daerah Jawa Barat ditampilkan secara terbatas karena minimnya arsip yang tersedia. Arsip yang ditampilkan antara lain mengenai resolusi pengusahaan sumber minyak tanah di daerah Indramayu pada 10 September 1957 serta pidato Presiden Soekarno saat pembukaan tambang emas di Cikotok, Sukabumi, pada 12 Juli 1958. Arsip-arsip ini memberikan gambaran mengenai upaya pengembangan sektor pertambangan di Jawa Barat pada masa tersebut.</span></p></div></div></div></div><div class=\"z-0 flex min-h-[46px] justify-start\"></div></div></div></section></div></div><div aria-hidden=\"true\" class=\"pointer-events-none -mt-px h-px translate-y-[calc(var(--scroll-root-safe-area-inset-bottom)-14*var(--spacing))]\"></div><!--EndFragment--></div>', '<div style=\"text-align: justify;\"><!--StartFragment--><div class=\"qMYqUG_convSearchResultHighlightRoot\"><div class=\"\" data-turn-id-container=\"request-WEB:e6a54c7f-54bf-4121-9744-7bbafc4dff28-3\" data-is-intersecting=\"true\"><section class=\"text-token-text-primary w-full focus:outline-none has-data-writing-block:pointer-events-none [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto R6Vx5W_threadScrollVars scroll-mb-[calc(var(--scroll-root-safe-area-inset-bottom,0px)+var(--thread-response-height))] scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" data-turn-id=\"request-WEB:e6a54c7f-54bf-4121-9744-7bbafc4dff28-3\" data-turn-id-container=\"request-WEB:e6a54c7f-54bf-4121-9744-7bbafc4dff28-3\" data-testid=\"conversation-turn-8\" data-scroll-anchor=\"false\" data-turn=\"assistant\"><div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)\"><div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\"><div class=\"flex max-w-full flex-col gap-4 grow\"><div data-message-author-role=\"assistant\" data-message-id=\"cce3f6f4-a1b4-483b-a7e8-ef28abf4bff4\" dir=\"auto\" data-message-model-slug=\"gpt-5-5\" class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1\" data-turn-start-message=\"true\" tabindex=\"0\"><div class=\"flex w-full flex-col gap-1 empty:hidden\"><div class=\"markdown prose dark:prose-invert wrap-break-word w-full dark markdown-new-styling\"><p data-start=\"0\" data-end=\"459\" data-is-last-node=\"\" data-is-only-node=\"\" style=\"text-align: justify; \"><span style=\"font-size: 12pt;\">Mining aspects in the West Java Regional Image are shown in a limited way due to the lack of available archives. The archives displayed include the resolution regarding the exploitation of kerosene resources in the Indramayu area on 10 September 1957 as well as President Soekarno\'s speech at the opening of a gold mine in Cikotok, Sukabumi, on 12 July 1958. These archives provide an overview of efforts to develop the mining sector in West Java at that time.</span></p></div></div></div></div><div class=\"z-0 flex min-h-[46px] justify-start\"></div></div></div></section></div></div><div aria-hidden=\"true\" class=\"pointer-events-none -mt-px h-px translate-y-[calc(var(--scroll-root-safe-area-inset-bottom)-14*var(--spacing))]\"></div><!--EndFragment--></div>', '[\"features/slideshow/FiEgKI3xxBBwLw5531bwcy6xuEjk0BDo6AZFWjxg.png\", \"features/slideshow/gZiT9aNv0f6ZJJIUMucew3ZnjiJBU7XoHY6nvrS8.png\"]', NULL, NULL, NULL, NULL, 'right', '#ffffff', '{\"carousel_media_type\": \"images\", \"unified_image_order\": [{\"type\": \"upload\", \"uploadIndex\": 0}, {\"type\": \"upload\", \"uploadIndex\": 1}], \"carousel_video_order\": []}', 11, '2026-05-25 07:01:22', '2026-05-25 08:25:56'),
(67, 72, 14, 'text_carousel', 'K. Transportasi dan Komunikasi', 'K. Transportation and Communication', NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 12pt; font-family: inherit;\">Perkembangan jaringan Transportasi digambarkan melalui Grafik tentang biaya pekerjaan stasiun kereta api jalur Priangan- Cilacap, 1890, arsip-arsip foto seperti Kereta Api sedang langsir di Stasiun Bandung 1952, Stasiun Kereta Api Bandung, 27 Juli 1953, Stasiun Kereta Api di Cirebon, 15 November 1953, pesawat terbang Garuda Indonesia Airways sedang mendarat di lapangan terbang Andir Bandung pada tanggal 10 September 1949, Model angkutan Becak sebagai salah satu alat transportasi di kota Bandung 1953, Pemandangan di sekitar pelabuhan Cirebon dimana terlihat pangkalan kapal-kapal penarik sampan tempat kapal berlabuh 1953, Nota Kepala Dinas Interlokal tentang Organisasi Dinas Interlokal, 15 Mei 1925, Surat tentang perluasan gedung Kantor Pos Besar di Bandung, lampiran denah, 9 Oktober 1931, Kantor Pos Besar di Bandung, 27 Juli 1953, Kantor Pos dan Telepon di Bandung, 27 Juli 1953, Penyederhanaan Organisasi Post, Telegraaf dan Telefoon (PTT), 6 September 1935, dan Peraturan Pemerintah RI Nomor 24 Tahun 1984 tentang Pendirian Perusahaan Umum (Perum) Pos dan Giro, 4 September 1984.&nbsp;</span></div>', '<div style=\"text-align: justify;\"><span style=\"font-size: 12pt; font-family: inherit;\">The development of the transportation network is depicted through graphs regarding the cost of work on the Priangan-Cilacap train station line, 1890, archive photos such as the train being rolled over at Bandung Station 1952, Bandung Train Station, July 27 1953, Cirebon Train Station, November 15 1953, Garuda Indonesia Airways airplane landing at Andir Bandung airfield on September 10 1949, Becak transport model as a means of transportation in the city of Bandung 1953, View around the port of Cirebon where you can see the base of the dinghy towing boats where the ships are anchored 1953, Note from the Head of the Interlocal Service regarding the Organization of the Interlocal Service, 15 May 1925, Letter regarding the expansion of the General Post Office building in Bandung, attached plan, 9 October 1931, Post Office in Bandung, 27 July 1953, Office Post and Telephone in Bandung, 27 July 1953, Simplification of the Post, Telegraph and Telephone (PTT) Organization, 6 September 1935, and Indonesian Government Regulation Number 24 of 1984 concerning the Establishment of Post and Giro Public Companies (Perum), 4 September 1984. </span></div>', '[\"features/slideshow/TQSStsHLCsalrvhHqFvbSkfHSo6XXA6jinH1FBQb.png\", \"features/slideshow/JHpNDqfm4Ig0vC5sJnITiQxPBuXMqGvnPoJT0Dy2.png\", \"features/slideshow/8SAq0EFlc0iZPw0OtGUPKLZfgc5IcD0iOd3L6Umn.png\", \"features/slideshow/JbjkXhTBLA5yO1pDMTK4fkSsg6tAEyVqnTR8aQOW.png\", \"features/slideshow/Dvq65OEIz1UyTKPyDNYdCbFUAlmJYbh5If6GGB9Z.png\", \"features/slideshow/VBwBH4Nq2QkwiIXOmRna2hhqBbmwerqPz4ya5Krr.png\", \"features/slideshow/NRqdBBjC4GzTPIWkXzdp0sbjK2dyO1OOuMZ5YhXu.png\", \"features/slideshow/7HW43mbKznu0uYpEYv2UGAWuW1MgfEbHO6NYyyfm.png\", \"features/slideshow/ClW5UQMDXwSFCjqyNIuhoOsJYqljhojUGbeOu1dW.png\", \"features/slideshow/8IEMs4b99rU5zv9S30XAxrxa4pXJ3L7KMpkXd4IM.png\", \"features/slideshow/Q7HA8dNF667wZlG8ybOj6Ex9qQ2IAL4k8NIJ2ZLY.png\", \"features/slideshow/8xSQKDt3CMShsIRLupKmnLdE67N2eX88CT3v9BXc.png\", \"features/slideshow/3baDUgz9dSnbK2X5y2sPS7O3lkFg7j29SAzSO3Fu.png\"]', NULL, NULL, NULL, NULL, 'right', '#ffffff', '{\"carousel_media_type\": \"images\", \"unified_image_order\": [{\"type\": \"upload\", \"uploadIndex\": 0}, {\"type\": \"upload\", \"uploadIndex\": 1}, {\"type\": \"upload\", \"uploadIndex\": 2}, {\"type\": \"upload\", \"uploadIndex\": 3}, {\"type\": \"upload\", \"uploadIndex\": 4}, {\"type\": \"upload\", \"uploadIndex\": 5}, {\"type\": \"upload\", \"uploadIndex\": 6}, {\"type\": \"upload\", \"uploadIndex\": 7}, {\"type\": \"upload\", \"uploadIndex\": 8}, {\"type\": \"upload\", \"uploadIndex\": 9}, {\"type\": \"upload\", \"uploadIndex\": 10}, {\"type\": \"upload\", \"uploadIndex\": 11}, {\"type\": \"upload\", \"uploadIndex\": 12}], \"carousel_video_order\": []}', 12, '2026-05-25 07:03:27', '2026-05-26 02:14:43'),
(68, 72, 14, 'text_carousel', 'L. Agama', 'L. Religion', NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-family: inherit; font-size: 12pt;\">Kegiatan Keagamaan digambarkan melalui foto-foto tempat peribadatan yang tersebar di berbagai tempat, seperti foto gereja di Depok tahun 1949, Gereja Katolik Roma di Bandung tahun 1953, Gereja Protestan Bandung 1953, Masjid Agung Sukabumi 1952, Masjid Kanoman Cirebon 1953, dan Masjid Agung Bandung 1957. Selain itu terdapat foto Presiden Soekarno sedang melaksanakan Sholat Idul Adha di Alun-alun Sukabumi pada tanggal 31 Agustus 1952, Perayaan hari Whu Chang oleh bangsa Tionghoa golongan Kuo Min Tang di Bandung, 10 Oktober 1953 dan kegiatan Renungan tahun baru 1990 di Paseban Tri Panca Tunggal Cigugur Kabupaten Kuningan Jawa Barat yang dilakukan oleh 80 orang anggota pemuda Hindu Indonesia Provinsi Jawa Barat.</span></div>', '<div style=\"text-align: justify;\"><span style=\"font-family: inherit; font-size: 12pt;\">Religious activities are depicted through photographs of places of worship scattered in various places, such as photos of churches in Depok in 1949, the Roman Catholic Church in Bandung in 1953, the Bandung Protestant Church in 1953, the Sukabumi Grand Mosque in 1952, the Kanoman Mosque in Cirebon in 1953, and the Bandung Grand Mosque in 1957. Apart from that, there is a photo of President Soekarno carrying out Eid al-Adha prayers in Sukabumi Square on 31 August 1952, Whu Chang Day celebrations by the Chinese Kuo Min Tang group in Bandung, 10 October 1953 and 1990 New Year devotional activities at Paseban Tri Panca Tunggal Cigugur, Kuningan Regency, West Java, carried out by 80 members of the Indonesian Hindu youth of West Java Province.</span></div>', '[\"features/slideshow/peXeNLco88FJz3i2GT1tmAF1QcjKk4Ze1eDScSTF.png\", \"features/slideshow/10XnglRt46TEQ3b3UzGamnylrY3hPMi4VB4m8iF9.png\", \"features/slideshow/6Kq0thBs4ncKmhC6vrIeBA7rOGSQcqEvKVTnSPpx.png\", \"features/slideshow/LFPTK2tAhlFtvNTJLbPL2kGHDJLoAscdPpcQi8f1.png\", \"features/slideshow/nQIzMUHHsp03sCc5jTAT7pmvhIW8EmVLiDRV963U.png\", \"features/slideshow/FBALV939Be3oFuneBn3saTZS8s9UqAB9h917vaPy.png\", \"features/slideshow/ehdJfRPyMAVgM8COmmXdbBzVz04PBR8ZcuJ9a3Nb.png\", \"features/slideshow/70w73XFbAhsMTDq2a8sxsLoXKEEW0X4anjyoS9qG.png\", \"features/slideshow/KAyIhM1SQD4qv4feiQtGo0lcAkDcaXOaYoX3wlev.png\"]', NULL, NULL, NULL, NULL, 'right', '#ffffff', '{\"carousel_media_type\": \"images\", \"unified_image_order\": [{\"type\": \"upload\", \"uploadIndex\": 0}, {\"type\": \"upload\", \"uploadIndex\": 1}, {\"type\": \"upload\", \"uploadIndex\": 2}, {\"type\": \"upload\", \"uploadIndex\": 3}, {\"type\": \"upload\", \"uploadIndex\": 4}, {\"type\": \"upload\", \"uploadIndex\": 5}, {\"type\": \"upload\", \"uploadIndex\": 6}, {\"type\": \"upload\", \"uploadIndex\": 7}, {\"type\": \"upload\", \"uploadIndex\": 8}], \"carousel_video_order\": []}', 13, '2026-05-25 07:04:39', '2026-05-26 02:15:40'),
(69, 72, 14, 'text_carousel', 'M. Kebudayaan dan Olahraga', 'M. Culture and Sports', NULL, NULL, '<div style=\"text-align: justify;\"><!--StartFragment--><p>Koleksi arsip mengenai Aktivitas Kebudayaan dan Olahraga di Jawa Barat menampilkan beragam dokumentasi sejarah dalam bentuk foto dan berkas dari tahun 1950–1976. Arsip ini merekam kekayaan seni dan budaya Sunda, seperti pertunjukan Tari Kelana Sunda di Bandung tahun 1950, Orkes Angklung oleh Badan Kesenian Indonesia tahun 1951, Tari Wayang Sunda, Wayang Golek, hingga seperangkat gamelan Sunda yang digunakan dalam pertunjukan tari di Gubernuran Bandung tahun 1955. Selain itu, terdapat dokumentasi tradisi budaya di Cirebon seperti rombongan “Panjang Jimat”, pertunjukan Wayang Kulit pada upacara Lumban, serta Gua Sunyaragi yang menjadi bagian dari sejarah Kesultanan Cirebon.</p><p>Di bidang olahraga, arsip ini juga memuat dokumentasi penyelenggaraan Pekan Olahraga Nasional (PON) V di Bandung tahun 1961, antara lain naskah pidato Presiden Soekarno pada upacara pembukaan, foto kontingen Jawa Barat, dan regu basket putri sebelum pertandingan. Selain dokumentasi budaya dan olahraga, koleksi ini juga mencakup berkas pendaftaran benda antik “Piring Cupang Sandang” tahun 1976 yang disertai gambar. Keseluruhan arsip menjadi sumber penting untuk melihat perkembangan kebudayaan, tradisi, serta aktivitas olahraga di Jawa Barat pada masa pascakemerdekaan.</p></div>', '<div style=\"text-align: justify;\"><!--StartFragment--><p>The archive collection regarding Cultural and Sports Activities in West Java displays various historical documentation in the form of photos and files from 1950–1976. This archive records the richness of Sundanese art and culture, such as the Sundanese Kelana Dance performance in Bandung in 1950, the Angklung Orchestra by the Indonesian Arts Agency in 1951, the Sundanese Wayang Dance, Wayang Golek, to a set of Sundanese gamelan used in dance performances in Bandung Governorate in 1955. Apart from that, there is documentation of cultural traditions in Cirebon such as the \"Panjang Jimat\" troupe, the Shadow Puppet performance at the Lumban ceremony, and the Sunyaragi Cave which became part of the history of the Cirebon Sultanate.</p><p>In the sports sector, this archive also contains documentation of the implementation of the V National Sports Week (PON) in Bandung in 1961, including the text of President Soekarno\'s speech at the opening ceremony, photos of the West Java contingent, and the women\'s basketball team before the match. Apart from cultural and sports documentation, this collection also includes a registration file for the 1976 antique \"Pairing Betta Clothing\" accompanied by pictures. The entire archive is an important source for viewing the development of culture, traditions and sports activities in West Java in the post-independence period.</p></div>', '[\"features/slideshow/xu4N1AY3uxvmnOnMVvKodl8sestqU2hpu2jQHgqK.png\", \"features/slideshow/dBCcEA0NLwSKKINriDkTNpBDEHV6LUjZpBq1bmbB.png\", \"features/slideshow/pm2HRBw7j1XvBIDJWgVUoBRjl8JrLPFBpGoo05pw.png\", \"features/slideshow/EjhqKOTSxu0DpQrbHHjsewS8VEHNi2RX3aaKAjif.png\", \"features/slideshow/UPfp3zy2tWjw3FhNITUf5qmwUcJnbD2AdXoUVSAo.png\", \"features/slideshow/dKcwUJihP5R4RiroH03guoMVvb0Igt6DDn2Ffuft.png\", \"features/slideshow/gwq5RLW8bKs5xPS0UvXgpUFnav1MoM2rvuuHHLYa.png\", \"features/slideshow/k9V8T4ylFdS3vtfU2r4QjBU5O71BBZ8LDCBHBwnu.png\", \"features/slideshow/76BPBitjMsgnSNDrQv4XaO4Hd39ZWNV4dvJoVEeg.png\", \"features/slideshow/CTdNldJOVC6PNv6JqgnF80yIqAUYIQ8gR0ChZjsr.png\", \"features/slideshow/VSZskKZRqDt9kKoZgGZyOx0cWtqDgWhww8Za7S8c.png\", \"features/slideshow/IYo5ji0brAgKtfMtzoE3ZZeFW3Jn7njtGWMrKFuc.png\", \"features/slideshow/sEGHTqfIh7VdYeBM3PJRMx26M4HK8iNZOL50rN91.png\"]', NULL, NULL, NULL, NULL, 'right', '#ffffff', '{\"carousel_media_type\": \"images\", \"unified_image_order\": [{\"type\": \"upload\", \"uploadIndex\": 0}, {\"type\": \"upload\", \"uploadIndex\": 1}, {\"type\": \"upload\", \"uploadIndex\": 2}, {\"type\": \"upload\", \"uploadIndex\": 3}, {\"type\": \"upload\", \"uploadIndex\": 4}, {\"type\": \"upload\", \"uploadIndex\": 5}, {\"type\": \"upload\", \"uploadIndex\": 6}, {\"type\": \"upload\", \"uploadIndex\": 7}, {\"type\": \"upload\", \"uploadIndex\": 8}, {\"type\": \"upload\", \"uploadIndex\": 9}, {\"type\": \"upload\", \"uploadIndex\": 10}, {\"type\": \"upload\", \"uploadIndex\": 11}, {\"type\": \"upload\", \"uploadIndex\": 12}], \"carousel_video_order\": []}', 14, '2026-05-25 07:05:46', '2026-05-25 08:01:46'),
(70, 72, 14, 'text_carousel', 'N. Lingkungan Hidup', 'N. Environment', NULL, NULL, '<div style=\"text-align: justify;\"><!--StartFragment--><p>Koleksi arsip mengenai Keadaan Lingkungan Hidup dan Pesona Alam Jawa Barat menampilkan berbagai dokumentasi kondisi alam, lingkungan, serta bencana alam dari akhir abad ke-19 hingga tahun 1965. Arsip ini memuat foto-foto pemandangan alam yang menjadi ikon Jawa Barat, seperti Kawah Kamojang di Garut tahun 1949, Pemandian Salabintana Sukabumi tahun 1950, Gunung Tangkuban Perahu di Lembang yang sedang mengeluarkan lahar panas tahun 1950, Kebun Raya Bogor tahun 1951, serta air terjun Maribaya Bandung tahun 1958.</p><p>Selain menggambarkan keindahan alam, arsip ini juga merekam berbagai peristiwa lingkungan dan bencana alam, antara lain laporan banjir Kali Ciliwung di Bogor tahun 1895 yang menghancurkan bendungan dan permukiman, kerusakan tanggul Kali Cimanuk di Indramayu akibat banjir tahun 1957, hingga rumah-rumah penduduk yang runtuh akibat bencana tersebut. Koleksi ini juga memuat pidato Presiden Soekarno pada pemberian penghargaan Kota Garut sebagai juara lomba kebersihan kota tahun 1960, yang mencerminkan perhatian pemerintah terhadap lingkungan hidup dan tata kota. Pada bagian akhir, ditampilkan dokumentasi bencana tanah longsor di Sukabumi akibat hujan terus-menerus pada tahun 1965. Arsip-arsip ini menjadi sumber penting dalam melihat hubungan masyarakat Jawa Barat dengan lingkungan alam, sekaligus merekam dinamika bencana dan upaya pelestarian lingkungan pada masa itu.</p></div>', '<div style=\"text-align: justify;\"><!--StartFragment--><p>The archive collection regarding the State of the Environment and the Natural Charm of West Java displays various documentation of natural conditions, the environment and natural disasters from the end of the 19th century to 1965. This archive contains photographs of natural landscapes that have become icons of West Java, such as the Kamojang Crater in Garut in 1949, the Salabintana Sukabumi Baths in 1950, Mount Tangkuban Perahu in Lembang which was emitting hot lava in 1950, the Bogor Botanical Gardens in 1950 1951, as well as the Maribaya Bandung waterfall in 1958.</p><p>Apart from describing natural beauty, this archive also records various environmental events and natural disasters, including reports of the Ciliwung River flood in Bogor in 1895 which destroyed dams and settlements, damage to the Cimanuk River embankment in Indramayu due to the 1957 flood, and people\'s houses collapsing as a result of the disaster. This collection also contains President Soekarno\'s speech at the awarding of Garut City as champion of the 1960 city cleanliness competition, which reflects the government\'s attention to the environment and city planning. In the final part, documentation of the landslide disaster in Sukabumi due to continuous rain in 1965 is displayed. These archives are an important source in looking at the relationship between West Javanese society and the natural environment, as well as recording the dynamics of disasters and environmental conservation efforts at that time.</p></div>', '[\"features/slideshow/W2FCB5Qnur7N8frOAY2XsFup2FY92tGF0ygS8e19.png\", \"features/slideshow/xkxy6RWsi9VyPpBLGxZEZ0hNk2GDXOj2wjyIQxyA.png\", \"features/slideshow/cv1nxDUw2FCFMxq3X35nul7pYnDJc3L9gbG2moee.png\", \"features/slideshow/DcA3D2zBKFIoXiZuIth4GDMM9YkUuArKFHj7UJHk.png\", \"features/slideshow/EaQK4cV3AluaHZAuFBhD4ceST95DoEXValURzs5i.png\", \"features/slideshow/sYTCSVQGZvw24Sg3WG2wCE8mMl97MsIu2YbqSJFC.png\", \"features/slideshow/QUrlaIW6q6rWZ2wSVacBBY0cKdSQsFGxk5vTIzCX.png\", \"features/slideshow/26FntHaOa3aH6AamwOO3SOeB2deO9d5E2pHQDh9p.png\", \"features/slideshow/W8jrphiAjijyrXRFLLRjkVEEU2TDFsmx9OxjzfsC.png\", \"features/slideshow/RTo7xQTy973UPj9sL1j541As3xqi2aMk86ALzq4q.png\"]', NULL, NULL, NULL, NULL, 'right', '#ffffff', '{\"carousel_media_type\": \"images\", \"unified_image_order\": [{\"type\": \"upload\", \"uploadIndex\": 0}, {\"type\": \"upload\", \"uploadIndex\": 1}, {\"type\": \"upload\", \"uploadIndex\": 2}, {\"type\": \"upload\", \"uploadIndex\": 3}, {\"type\": \"upload\", \"uploadIndex\": 4}, {\"type\": \"upload\", \"uploadIndex\": 5}, {\"type\": \"upload\", \"uploadIndex\": 6}, {\"type\": \"upload\", \"uploadIndex\": 7}, {\"type\": \"upload\", \"uploadIndex\": 8}, {\"type\": \"upload\", \"uploadIndex\": 9}], \"carousel_video_order\": []}', 15, '2026-05-25 07:06:30', '2026-05-25 08:10:55'),
(75, 72, 16, 'hero', NULL, NULL, NULL, NULL, '<p style=\"text-align: justify;\"><span style=\"font-size: 12pt; color: rgb(255, 255, 255);\">Arsip Nasional Republik Indonesia (ANRI) telah menerbitkan Naskah Sumber Arsip (NSA) Seri Teh Priangan pada tahun 2016 sebagai salah satu upaya pelestarian dan pemanfaatan arsip statis yang berkaitan dengan sejarah perkebunan teh di Indonesia, khususnya di wilayah Priangan, Jawa Barat. Publikasi ini telah tersedia dan dapat diakses melalui situs resmi ANRI maupun portal layanan pemanfaatan arsip ANRI.</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 12pt; color: rgb(255, 255, 255);\">Melalui Naskah Sumber Arsip Seri Teh Priangan, ANRI menghadirkan arsip-arsip yang merekam perjalanan sejarah perkebunan teh di wilayah Priangan, mulai dari pembukaan lahan perkebunan, sistem pengelolaan, produksi, hingga peranan teh dalam kehidupan sosial dan ekonomi masyarakat. Kehadiran naskah sumber arsip ini diharapkan dapat menjadi sumber informasi, referensi penelitian, serta sarana edukasi bagi masyarakat untuk memahami sejarah panjang teh sebagai salah satu komoditas penting di Ind</span></p>', '<p style=\"text-align: justify;\"><span style=\"font-size: 12pt; color: rgb(255, 255, 255);\">The National Archives of the Republic of Indonesia (ANRI) published the Priangan Tea Series Archive Source Manuscript (NSA) in 2016 as an effort to preserve and utilize static archives relating to the history of tea plantations in Indonesia, especially in the Priangan area, West Java. This publication is available and can be accessed via the official ANRI website and the ANRI archive utilization service portal.</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 12pt; color: rgb(255, 255, 255);\">Through the Priangan Tea Series Archive Source Manuscripts, ANRI presents archives that record the history of tea plantations in the Priangan area, starting from plantation land clearing, management systems, production, to the role of tea in the social and economic life of the community. It is hoped that the presence of this archival source text can become a source of information, research reference, and educational tool for the public to understand the long history of tea as an important commodity in Indonesia</span></p>', '[\"features/slideshow/fMfldyVkcVeGOUY1cmwkl47mkFDo5wp44XSYcAoe.jpg\"]', NULL, NULL, NULL, NULL, 'center', '#ffffff', '{\"unified_image_order\": [{\"type\": \"upload\", \"uploadIndex\": 0}]}', 1, '2026-05-26 03:54:18', '2026-06-14 07:04:29'),
(76, 72, 16, 'text_carousel', 'A. Awal Masa Penanaman Teh', 'A. Early Tea Planting Period', NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-family: inherit; font-size: 12pt;\">Teh bukan merupakan tanaman asli dari Indonesia, tanaman teh didatangkan dari negara lain untuk ditanam di Indonesia (Hindia Belanda pada waktu itu). Adanya perkebunanperkebunan pada waktu itu tidak lepas dari usaha yang dilakukan oleh pemerintah Belanda untuk mengusahakan penanaman tanaman yang bernilai ekspor. Dalam pembukaan perkebunan teh tentu saja selain membutuhkan lahan-lahan yang disiapkan untuk ditanami maka kebutuhan akan bibit teh menjadi hal yang utama. Untuk memenuhi kebutuhan bibit teh maka pemerintah Belanda memulai dengan mengirimkan utusan-utusan untuk mendapatkan bibit baik ke Negeri Cina (Tiongkok sekarang) maupun ke negara lain.</span></div>', '<div style=\"text-align: justify;\"><span style=\"font-family: inherit; font-size: 12pt;\">Tea is not a native plant from Indonesia, tea plants were imported from other countries to be planted in Indonesia (the Dutch East Indies at that time). The existence of plantations at that time could not be separated from the efforts made by the Dutch government to cultivate crops with export value. In opening a tea plantation, of course, apart from requiring land that is prepared for planting, the need for tea seeds is the main thing. To meet the need for tea seeds, the Dutch government started by sending envoys to obtain seeds both to China (now China) and to other countries.</span></div>', '[\"features/slideshow/dsQu7bHzxevmPd2Ts6Uadj2YDJSHwf2HB5A4aVht.png\", \"features/slideshow/ulS0qcPyXa12x0tA6EM5PMhbLsGKoNrCv0bxqxjG.png\", \"features/slideshow/9yDJE6S8oiNyaHjrdDi2lk7r958RCMgvljFD7vBm.png\", \"features/slideshow/IL2jBeOA5meMr7FbDFpFNsNvZyoczp8Rwg2dV2Vb.png\", \"features/slideshow/lIcqkz1qpknSm9kD41o3nsLhaM57xIc2ZSek5ABT.png\", \"features/slideshow/tpO8Qy8Sa5iRfDXHDMFqX7FUMuhw62VSZBfZWIjl.png\"]', NULL, NULL, NULL, NULL, 'right', '#ffffff', '{\"0\": \"<span style=\\\"font-size: 12pt;\\\">Konsiderasi dan Advis tanggal 19 Februari 1832 No. 207 untuk mengijinkan J.J.L. Jacobson untuk pergi ke Cina guna mendapatkan bibit teh dan beberapa orang Cina untuk bekerja di perkebunan teh pemerintah.</span><br><a href=\\\"https://www.anri.go.id/download/daftar-arsip-tekstual-cultures-arsip-perkebunan-18161900-1585906438\\\" class=\\\"rte-btn-link\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" style=\\\"display: inline-flex; align-items: center; justify-content: center; background-color: rgb(13, 110, 253); color: rgb(255, 255, 255); padding: 10px 24px; border-radius: 8px; font-weight: 600; text-align: center; margin: 8px 0px; box-shadow: rgba(0, 0, 0, 0.1) 0px 2px 4px;\\\">ANRI K.68</a>\", \"1\": \"<div style=\\\"text-align: justify;\\\"><span style=\\\"font-size: 12pt;\\\">Ekstrak Resolusi dari Register Resolusi GG NI tanggal 12 September 1832 tentang keputusan penanaman 1 miljoen (juta) batang/bibit teh di Bodja Negara yang termasuk residensi Preanger Regetschappen dan 50.000 bibit di Tjiseroepan di Preanger Regentschappen.<br></span><a href=\\\"https://www.anri.go.id/download/daftar-arsip-tekstual-cultures-arsip-perkebunan-18161900-1585906438\\\" class=\\\"rte-btn-link\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" style=\\\"display: inline-flex; align-items: center; justify-content: center; background-color: rgb(13, 110, 253); color: rgb(255, 255, 255); padding: 10px 24px; border-radius: 8px; font-weight: 600; text-align: center; margin: 8px 0px; box-shadow: rgba(0, 0, 0, 0.1) 0px 2px 4px;\\\">ANRI K.68</a><span style=\\\"font-size: 12pt;\\\"></span></div>\", \"2\": \"<div style=\\\"text-align: justify;\\\"><span style=\\\"font-size: 12pt;\\\">Ekstrak Resolusi dari Register Resolusi Gubernur Jenderal Nederlandsch Indie tanggal 5 Maret 1832 No. 4 tentang pemberian kredit untuk pembukaan perkebunan teh serta mengangkat J.J.L. Jacobson sebagai Inspektur Perkebunan Teh.</span></div><div><a href=\\\"https://www.anri.go.id/download/daftar-arsip-tekstual-cultures-arsip-perkebunan-18161900-1585906438\\\" class=\\\"rte-btn-link\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" style=\\\"display: inline-flex; align-items: center; justify-content: center; background-color: rgb(13, 110, 253); color: rgb(255, 255, 255); padding: 10px 24px; border-radius: 8px; font-weight: 600; text-align: center; margin: 8px 0px; box-shadow: rgba(0, 0, 0, 0.1) 0px 2px 4px;\\\">ANRI K.68</a><span style=\\\"font-size: 12pt;\\\"></span></div>\", \"3\": \"<div style=\\\"text-align: justify;\\\"><span style=\\\"font-size: 12pt;\\\">Surat dari Residen Krawang kepada Dewan Hindia, tentang penerimaan bibit pohon teh, tanggal 13 Februari 1833.<br></span><a href=\\\"https://www.anri.go.id/download/daftar-arsip-tekstual-cultures-arsip-perkebunan-18161900-1585906438\\\" class=\\\"rte-btn-link\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" style=\\\"display: inline-flex; align-items: center; justify-content: center; background-color: rgb(13, 110, 253); color: rgb(255, 255, 255); padding: 10px 24px; border-radius: 8px; font-weight: 600; text-align: center; margin: 8px 0px; box-shadow: rgba(0, 0, 0, 0.1) 0px 2px 4px;\\\">ANRI K.68</a><span style=\\\"font-size: 12pt;\\\"></span></div>\", \"4\": \"<div style=\\\"text-align: justify;\\\"><span style=\\\"font-size: 12pt;\\\">Laporan Bupati Krawang atas penggunaan uang sebesar 195 gulden untuk biaya pengangkutan peti teh, Purwakarta 29 Januari 1833.<br></span><a href=\\\"https://www.anri.go.id/download/daftar-arsip-tekstual-cultures-arsip-perkebunan-18161900-1585906438\\\" class=\\\"rte-btn-link\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" style=\\\"display: inline-flex; align-items: center; justify-content: center; background-color: rgb(13, 110, 253); color: rgb(255, 255, 255); padding: 10px 24px; border-radius: 8px; font-weight: 600; text-align: center; margin: 8px 0px; box-shadow: rgba(0, 0, 0, 0.1) 0px 2px 4px;\\\">ANRI K.68</a><span style=\\\"font-size: 12pt;\\\"></span></div>\", \"5\": \"<div style=\\\"text-align: justify;\\\"><span style=\\\"font-size: 12pt;\\\">Ringkasan dari Daftar Keputusan Gubernur Jenderal ad interim No. 3, 27 Agustus 1835.<br></span><a href=\\\"https://www.anri.go.id/download/daftar-arsip-tekstual-cultures-arsip-perkebunan-18161900-1585906438\\\" class=\\\"rte-btn-link\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" style=\\\"display: inline-flex; align-items: center; justify-content: center; background-color: rgb(13, 110, 253); color: rgb(255, 255, 255); padding: 10px 24px; border-radius: 8px; font-weight: 600; text-align: center; margin: 8px 0px; box-shadow: rgba(0, 0, 0, 0.1) 0px 2px 4px;\\\">ANRI K.68</a><span style=\\\"font-size: 12pt;\\\"></span></div>\", \"carousel_media_type\": \"images\", \"unified_image_order\": [{\"type\": \"upload\", \"uploadIndex\": 0}, {\"type\": \"upload\", \"uploadIndex\": 1}, {\"type\": \"upload\", \"uploadIndex\": 2}, {\"type\": \"upload\", \"uploadIndex\": 3}, {\"type\": \"upload\", \"uploadIndex\": 4}, {\"type\": \"upload\", \"uploadIndex\": 5}], \"carousel_video_order\": []}', 2, '2026-05-26 04:02:51', '2026-05-26 07:19:01');
INSERT INTO `virtual_slideshow_slides` (`id`, `feature_id`, `feature_page_id`, `slide_type`, `title`, `title_en`, `subtitle`, `subtitle_en`, `description`, `description_en`, `images`, `image_urls`, `video_url`, `video_file`, `carousel_video_urls`, `layout`, `bg_color`, `info_popup`, `order`, `created_at`, `updated_at`) VALUES
(77, 72, 16, 'text_carousel', 'B. Lokasi Perkebunan dan Perluasan Lahan', 'B. Plantation Locations and Land Expansion', NULL, NULL, '<div style=\"text-align: justify;\"><span style=\"font-size: 12pt;\">Tanaman teh dapat tumbuh subur di daerah-daerah dengan ketinggian 200-2.000 meter di atas permukaan laut. Di daerah- daerah yang rendah umumnya tanaman teh kurang dapat menghasilkan teh yang berkualitas tinggi. Sehingga banyak perkebunan- perkebunan teh berada di daerah pegunungan. Di Indonesia tanaman teh diusahakan di daerah-daerah pegunungan. Salah satu daerah pegunungan adalah Priangan atau Jawa Barat yang pada masa kolonial dikenal dengan sebutan Preanger Regentschap. Daerah ini memiliki udara sejuk dan tanah yang subur. Daerah ini merupakan daerah pilihan pertama yang diujicobakan untuk ditanami dengan bibit teh yang dibawa dari Cina karena daerah Priangan merupakan daerah yang terletak di daerah pegunungan di bagian barat pulau Jawa atau Jawa Barat.</span></div>', '<div style=\"text-align: justify;\"><span style=\"font-size: 12pt;\">Tea plants can thrive in areas with an altitude of 200-2,000 meters above sea level. In low-lying areas, tea plants are generally less able to produce high quality tea. So many tea plantations are located in mountainous areas. In Indonesia, tea plants are cultivated in mountainous areas. One of the mountainous areas is Priangan or West Java, which during colonial times was known as Preanger Regentschap. This area has cool air and fertile soil. This area was the first choice area to be tested for planting with tea seeds brought from China because the Priangan area is an area located in a mountainous area in the western part of the island of Java or West Java.</span></div>', '[\"features/slideshow/JTk25rXB8tmllWeNqou3YeBMDOvZ8TfpfGWRzumr.png\", \"features/slideshow/yGhYik3bxIlohRotfIEE0ZbNExlwEXn5FGZlXBTH.png\", \"features/slideshow/J6p7noMNPZSYXQxLD6oe8oIZ6OzBEsb5LFwPaubQ.png\", \"features/slideshow/x1PJtwpyy6DIf4Ix2Z92DTrzv0rICQ8plS